// De statusregel: wat is er geladen, en loopt er nog iets?
//
// Gedragsbron: het setStatus-blok in de bevroren viewer (renderStatus). De
// telling is dezelfde en gebruikt dezelfde stringtabelsleutels — inclusief de
// twee correcties die de regel laten kloppen met wat de pagina TOONT:
// beëindigde besluiten hebben geen policy-object maar wel een kaart
// (stubOnlyContainers), en verzoeken tellen apart, niet bij de beleidssets.
import { Show } from 'solid-js';
import { stubOnlyContainers, t } from '../../model-grens.js';
import { vocabulaireNaam } from '../../model/default-corpus.js';
import {
  bronnen, compatIndex, endpoint, fouten, laadMelding, laadStatus, lijstFase, lijstFout,
  model, motor, quadCount, scopeNietGevonden,
} from '../../stores/corpus.js';
import type { CorpusFout, CorpusModel } from '../../stores/corpus.js';
import { melding, meldingVars, tekst, weergave } from '../../stores/weergave.js';
import { gedekteKnopen } from '../kaart/formulier-model.js';

/** De telling als platte tekst. Pure functie (geen DOM, geen store) zodat de
 *  parity met de oude regel los toetsbaar is. */
export function statustekst(
  m: CorpusModel,
  ctx: {
    bronnen: number; quads: number; fouten: CorpusFout[]; lang?: string;
    /** Het actieve SPARQL-endpoint; komt achter de tellingen te staan. */
    endpoint?: string | null;
    /** Fase 1 van de tweefasige lijstlading: de getallen zijn dan die van de
     *  AFGEKAPTE eerste slag en dat moet erbij staan, anders leest de regel als
     *  een eindtelling. */
    eersteBeeld?: boolean;
    /** Is de index via de vijf platte deelqueries opgebouwd? */
    compat?: boolean;
    /** BEVINDING I-6. Er stond een `?policy=` of `?set=` in de URL, maar hij
     *  wijst in de geladen bronnen niets aan. De bevroren viewer zet dat als
     *  `scopeNote` achter de tellingen (applyScopeAndRender, doc.js
     *  r.1230-1238); zonder die regel snoeit de pagina niets en zegt zij ook
     *  niet waarom — de lezer ziet dan het volledige corpus en denkt dat zijn
     *  deeplink werkte. */
    scopeNietGevonden?: 'policy' | 'set' | null;
    /** HOEVEEL KNOPEN EEN GELADEN FORMULIER-SHAPE DRAAGT (10 sep 2026).
     *
     *  Een profiel dat formulier-shapes meebrengt beschrijft knopen die deze
     *  viewer zelf niet kent — bij een domeinprofiel de GLS-laag: dataproduct,
     *  leversets, distributies, gegevensvelden, afspraken en de rol-objecten.
     *  Ze zijn sinds deze ronde uitklapbaar onder de rij die ernaar verwijst,
     *  en dan hoort de regel die het corpus opsomt ze ook te tellen: zonder die
     *  telling is de enige manier om te weten dát ze er zijn, ze toevallig
     *  tegenkomen.
     *
     *  NUL IS GEEN TELLING. Draagt geen enkele bron een formulier-shape — het
     *  gewone geval, en elk corpus zonder profiel — dan staat het segment er
     *  niet. Een "0 gespecificeerde objecten" op elke gewone ODRL-bron zou een
     *  mededeling zijn over iets wat de lezer niet mist. */
    gedekt?: number;
  },
): string {
  // De taal mag expliciet mee. Zonder argument geldt de actieve taal van de
  // modellaag (t()'s eigen default); mét argument is de functie ook bruikbaar
  // als reactieve leesplek — de aanroeper leest dan weergave.lang.
  const tt = (k: string, v?: Record<string, unknown>) => t(k, v, ctx.lang);
  const c = m.counts;
  const beeindigd = stubOnlyContainers(m, 'agreement').length;
  const verzoeken = (m.sets || []).filter((s) => s.isRequest).length;
  const setNote = tt('status.sets', { n: c.sets - verzoeken }) + ', '
    + (verzoeken ? tt('status.requests', { n: verzoeken }) + ', ' : '');
  const vcNote = c.versionContainers
    ? tt('status.versionContainers', { n: c.versionContainers }) + ', ' : '';
  const errNote = ctx.fouten.length ? tt('status.errors', { n: ctx.fouten.length }) : '';
  // Het endpoint achter de tellingen (doc.js `extraNote`, gezet in bootFromParams).
  const epNote = ctx.endpoint ? tt('status.sparqlNote', { ep: ctx.endpoint }) : '';
  // Terugval-signaal: het endpoint kon de volledige-indexquery niet aan en de
  // index is via de vijf platte deelqueries opgebouwd. Klein en feitelijk — de
  // pagina toont dezelfde gegevens, alleen anders opgehaald. Niet tijdens fase 1,
  // want dan is er nog geen volledige index om iets over te zeggen.
  const compatNote = (!ctx.eersteBeeld && ctx.compat) ? tt('status.compatIndex') : '';
  // De scope-notitie hoort VÓÓR de foutentelling: dat is de volgorde van
  // renderStatus (`${baseNote}${extraNote}${scopeNote}`.trim() + errNote).
  const scopeNote = ctx.scopeNietGevonden === 'policy' ? tt('status.policyNotFound')
    : (ctx.scopeNietGevonden === 'set' ? tt('status.setNotFound') : '');
  // Zelfde volgorde als renderStatus in de bevroren viewer: tellingen, spatie,
  // de notities, dan fouten, dan de compat- en eerste-beeld-markering.
  return tt('status.sources', { n: ctx.bronnen }) + ', '
    + tt('status.triples', { n: ctx.quads }) + ' · '
    + tt('status.offers', { n: c.offers }) + ', '
    + tt('status.agreements', { n: c.agreements + beeindigd }) + ', ' + setNote
    // De notities krijgen één spatie na de artefacttelling en worden zelf
    // getrimd — precies de `${…} ` + `${…}`.trim()-greep van renderStatus, want
    // status.sparqlNote begint met zijn eigen ' · '.
    // De gedekte knopen staan ACHTER de artefacten: beide zijn geen policy maar
    // iets waar een policy naar wijst, en de artefacttelling is de vaste laatste
    // van de reeks — daar sluit deze bij aan in plaats van de bestaande volgorde
    // open te breken.
    + vcNote + `${tt('status.artifacts', { n: c.artifacts + c.bundles })}`
    + (ctx.gedekt ? ', ' + tt('status.specified', { n: ctx.gedekt }) : '') + ' '
    + `${epNote}${scopeNote}`.trim()
    + errNote + compatNote
    + (ctx.eersteBeeld ? tt('status.firstView') : '');
}

export function Statusregel() {
  // tekst() (niet t()) is het idioom voor UI-strings: het leest de taal uit de
  // weergavestore en is daarmee reactief. De pure statustekst() hieronder mag
  // t() gebruiken — die krijgt zijn taal van de aanroeper.
  // De telling telt de BRONNEN van het corpus. Bijgeladen knopen staan sinds
  // fixronde 1 buiten `bronnen()` (zie corpus.ts), dus daar is geen filter voor
  // nodig; de endpoint-pseudobron (het lijstskelet) telt wél mee, precies als in
  // de bevroren viewer, want dát is de bron waar de pagina uit leest.
  //
  // DE VOCABULAIRE TELT NIET MEE (opruimpunt 41). Zij komt sinds 9 sep 2026
  // automatisch achter elke bestandslading aan, en ruling 21 zet haar als eigen
  // categorie ONDER het bronnenpaneel in plaats van in de bronnenlijst. Het
  // paneel doet dat ook (`bronnen.tsx` r.208-209, op `b.vocab`); deze regel
  // telde haar wél, en dan zeggen paneel en statusregel 1 tegen 3 op hetzelfde
  // corpus. `vocabulaireNaam` is letterlijk het predicaat waarmee
  // `stores/bronbeheer.ts` r.298 die `vocab`-vlag zet — één bron van waarheid,
  // zodat de twee niet opnieuw uit elkaar lopen.
  //
  // HIER EN NIET IN `bronnen()`. De reden daarvoor was dat die lijst een TWEEDE
  // afnemer had: `verken/verken.tsx` gaf hem als datasourcelijst mee aan de
  // Comunica-deeplink, en dáár hoorde de vocabulaire juist bij — zonder haar
  // verloor die query zijn labels. De verkenner is 16 sep 2026 gesloopt, dus die
  // tweede afnemer is er niet meer en de plaatsing is nu een VRIJE keuze. Ze
  // blijft staan zoals ze stond: de telling corrigeren waar zij gemaakt wordt
  // raakt precies wat punt 41 aanwijst, en `bronnen()` verbouwen is een eigen
  // besluit met eigen afnemers (het bronnenpaneel leest dezelfde lijst).
  const eigenBronnen = () => bronnen().filter((b) => !vocabulaireNaam(b.url));
  const telling = (m: CorpusModel) => statustekst(m, {
    bronnen: eigenBronnen().length, quads: quadCount(), fouten: fouten(),
    lang: weergave.lang,          // reactief: hertaalt zonder herladen
    endpoint: endpoint(),
    eersteBeeld: lijstFase() === 'eerste',
    compat: compatIndex(),
    scopeNietGevonden: scopeNietGevonden(),
    gedekt: gedekteKnopen(),
  });

  const foutregel = () => {
    const msg = fouten().map((f) => f.message).join('; ');
    // Welke slag faalde bepaalt de melding — niet "staat er toevallig nog een
    // model" (bevinding M-2). De twee endpointvormen komen letterlijk uit
    // loadFromSparql/loadPolicyList in de bevroren viewer.
    switch (lijstFout()) {
      case 'volledigeIndex': return tekst('err.sparqlFullIndex', { msg });
      case 'endpoint': return tekst('err.sparql', { msg });
      default: return tekst('err.srcLoad', { msg });
    }
  };

  const regel = () => {
    const m = model();
    // Een vluchtige mededeling staat in de plaats van de TELLING — het antwoord
    // op de handeling die de lezer zojuist deed, precies zoals setStatus de
    // regel overschrijft. Maar zij wijkt voor de LADING en voor een FOUT: die
    // twee gaan over de bruikbaarheid van de hele pagina en mogen nooit
    // onzichtbaar zijn achter een mededeling over één klik (bevinding NB-2).
    // Wat er ná die stand weer staat, komt uit de telling: de melding zelf
    // wordt gewist zodra er geladen of herbouwd wordt (zie app.tsx).
    const los = melding();
    if (los && laadStatus() !== 'laden' && laadStatus() !== 'fout') return tekst(los, meldingVars());
    switch (laadStatus()) {
      // FASE 1 van de tweefasige endpointlading is geen gewone laadstand: er
      // staan al echte kaarten. De regel toont dan de (afgekapte) tellingen met
      // status.firstView erachter en de spinner aan — zoals renderStatus dat
      // doet met zijn tweede argument.
      case 'laden':
        return (m && lijstFase() === 'eerste') ? telling(m) : tekst(laadMelding(), {
          ep: endpoint() ?? '',
        });
      case 'fout': return foutregel();
      case 'klaar': return m ? telling(m) : '';
      // DE LEGE START (9 sep 2026). Tot die dag was 'leeg' een uitrolgeval dat
      // in de praktijk niet voorkwam — er laadde altijd een voorbeeldcorpus — en
      // een blanco statusregel viel niemand op. Sinds de demobronnen niet meer
      // vanzelf laden is dit de NORMALE opening van de app, en dan is een lege
      // regel het verkeerde antwoord: de pagina lijkt te hangen. Hij zegt nu
      // gewoon wat er aan de hand is.
      case 'leeg': return tekst('status.leeg');
      default: return '';
    }
  };
  return (
    <p
      class="app-status"
      id="app-status"
      role="status"
      aria-live="polite"
      aria-busy={laadStatus() === 'laden' ? 'true' : 'false'}
      data-motor={motor() ?? undefined}
    >
      <Show when={regel()}>{(r) => <>{r()}</>}</Show>
    </p>
  );
}
