// DE ZIJNAV: de beleidshiërarchie als vaste kolom links, met een rail als
// dichte stand.
//
// Gedragsbron: het zijnav-blok van de bevroren viewer (viewer-bevroren/assets/doc.js,
// ensureTreeChrome … wireTree). Deze component bezit alles wat de PANE is —
// open/dicht, breedte, tekstfilter, Escape-laag — en laat de rijen aan
// <Boom/> en het filterveld aan <Filter/>.
//
// Wat vervalt: de renderTreeNav-machinerie. In de oude viewer werd de hele
// boom bij elke wijziging opnieuw getekend en moest elke standwissel dat zelf
// aanroepen; hier is de stand een signaal en volgt de DOM vanzelf. Wat BLIJFT
// is de reden achter die machinerie: een dichte boom bestáát niet (bij een
// groot corpus zijn dat honderden rijen die niemand ziet), dus <Show> haalt hem
// echt weg in plaats van hem op display:none te zetten.
import { createEffect, createMemo, createSignal, onCleanup, Show } from 'solid-js';
import { countNavRows, filterNav } from '../../model/parse.js';
import { prefGet, prefSet } from '../../model/prefs.js';
import { nav as volledigeNav, scopedNav } from '../../stores/corpus.js';
import { tekst, weergave } from '../../stores/weergave.js';
import { Boom } from './boom.jsx';
import type { NavKnoop } from './boom.jsx';
import { Filter } from './filter.jsx';

// Grenzen aan de sleepbare breedte: smaller dan 200px past geen enkel label
// meer, breder dan 560px eet de zijnav het document op. De standaard is
// dezelfde 280px als in de stylesheet.
export const TREE_W_MIN = 200;
export const TREE_W_MAX = 560;
export const TREE_W_DEF = 280;
// Trekken aan de RAIL is een tweede manier om te openen. Onder deze drempel is
// het gebaar nog een klik (die opent op de bewaarde breedte); daarboven wordt
// het een sleep die meteen op de sleepbreedte opent.
export const RAIL_SLEEP_DREMPEL = 40;

const klem = (px: number) => Math.max(TREE_W_MIN, Math.min(TREE_W_MAX, Math.round(px)));

/** De breedte staat als CSS-variabele op <html>, niet als inline width op de
 *  pane: de kantlijn van de body (en straks de ref-spiegel) leest dezelfde
 *  variabele en schuift dus mee. */
export function zetTreeBreedte(px: number): number {
  const w = klem(px);
  const wortel = typeof document !== 'undefined' && document.documentElement;
  if (wortel && wortel.style) wortel.style.setProperty('--tree-w', w + 'px');
  return w;
}

/** Open op een breed scherm, dicht op een smal (daar is de zijnav een overlay
 *  over het document). Zonder matchMedia: open. */
function openStandaard(): boolean {
  try { return !matchMedia('(max-width: 900px)').matches; } catch { return true; }
}

// Kwam deze klik van het TOETSENBORD? Enter/spatie op een knop levert een
// click-event met detail 0; een echte muisklik telt kliks.
const isToetsKlik = (e: MouseEvent) => !!e && e.detail === 0;

export interface ZijnavProps {
  /** Springen naar de kaart van deze knoop. Zolang de kaartenlijst er niet is
   *  doet de app-schil een anker-sprong op `data-ref`. */
  onSpring: (ref: string) => void;
}

export function Zijnav(props: ZijnavProps) {
  // De GEWENSTE stand van de lezer, los van wat er nu op het scherm staat:
  // zonder beleid is er geen nav en dus ook geen ingeschoven pagina, maar zodra
  // er weer beleid is hoort zijn keuze terug te komen.
  const [open, setOpen] = createSignal(!!prefGet('tree.open', openStandaard()));
  const [query, setQuery] = createSignal('');

  let paneel!: HTMLElement;
  let sluitKnop!: HTMLButtonElement;
  let railKnop!: HTMLButtonElement;
  let filterVeld: HTMLInputElement | null = null;

  // De ?set=-scoping wint van de volledige boom, precies als state.nav in
  // applyScopeAndRender; is er geen scoping (of vindt zij niets), dan is
  // scopedNav null en staat de hele boom er.
  const boomNav = createMemo<NavKnoop[]>(
    () => (scopedNav() ?? volledigeNav() ?? []) as NavKnoop[]);
  const heeftInhoud = () => boomNav().length > 0;
  const vraag = () => query().trim();
  const getoondeNav = createMemo<NavKnoop[]>(
    () => (vraag() ? filterNav(boomNav(), vraag()) : boomNav()));
  const totaal = createMemo(() => countNavRows(boomNav()));
  const getoond = createMemo(() => countNavRows(getoondeNav()));

  // De breedte van de vorige keer, VÓÓR de eerste render: anders schuift de
  // pagina zichtbaar van 280px naar de bewaarde breedte.
  zetTreeBreedte(Number(prefGet('tree.w', TREE_W_DEF)) || TREE_W_DEF);

  // De kantlijn van de pagina. Zonder beleid geen van beide: een kantlijn van
  // 280px naast niets is niet weg te klikken.
  createEffect(() => {
    const b = document.body;
    b.classList.toggle('tree-open', open() && heeftInhoud());
    b.classList.toggle('tree-rail-open', !open() && heeftInhoud());
  });
  onCleanup(() => {
    document.body.classList.remove('tree-open', 'tree-rail-open');
  });

  // `focusVolgt`: neem de focus mee naar de knop die de andere stand bedient.
  // Elke standwissel laat de knop verdwijnen die je zojuist gebruikte — de
  // sluitknop zit in de weggeklapte pane, de rail wijkt voor de pane. Alléén
  // bij toetsenbord: na een muisklik hoort de focus te vallen waar de browser
  // hem laat.
  function zetOpen(v: boolean, opties: { focusVolgt?: boolean } = {}) {
    setOpen(v);
    prefSet('tree.open', v);
    if (!opties.focusVolgt) return;
    const doel = v ? sluitKnop : railKnop;
    if (doel && !doel.hidden && doel.focus) doel.focus();
  }

  // --- Breedte: de sleeprand en de rail -------------------------------------
  // Eén sleepgebaar, gedeeld door de rand en de rail: pointerdown pakt vast, de
  // beweging komt van het DOCUMENT (de muis loopt zo van de smalle greep af) en
  // pointerup bewaart de uitkomst — één schrijfactie per gebaar, niet per pixel.
  let sleep:
    | { start: number; startW: number; opRail: boolean; geopend: boolean; w?: number }
    | null = null;

  /** De breedte die er NU staat, als getal. Nodig als terugvalpunt van een
   *  afgebroken sleep: de CSS-variabele is de enige plek waar de breedte tijdens
   *  het gebaar leeft (de voorkeur wordt pas bij loslaten geschreven). */
  function huidigeBreedte(): number {
    const wortel = typeof document !== 'undefined' && document.documentElement;
    const nu = wortel && wortel.style ? parseFloat(wortel.style.getPropertyValue('--tree-w')) : NaN;
    return Number.isFinite(nu) ? nu : (Number(prefGet('tree.w', TREE_W_DEF)) || TREE_W_DEF);
  }

  function startSleep(e: PointerEvent, opties: { vanaf: Element; opRail: boolean }) {
    // Alleen de primaire knop sleept: een rechtsklik op de rand of de rail zou
    // anders een gebaar starten dat pas bij de volgende klik eindigt.
    if (e.button && e.button !== 0) return;
    sleep = {
      start: Number(e.clientX) || 0, startW: huidigeBreedte(),
      opRail: opties.opRail, geopend: false,
    };
    if (e.preventDefault) e.preventDefault();
    // Niet elke omgeving kent setPointerCapture (jsdom, oudere browsers) — en
    // een mislukte capture mag het slepen niet blokkeren.
    try { opties.vanaf.setPointerCapture(e.pointerId); } catch { /* gaat ook zonder */ }
  }
  function beweegSleep(e: PointerEvent) {
    if (!sleep) return;
    const x = Number(e.clientX) || 0;
    if (sleep.opRail) {
      // Trekken aan de rail: pas voorbij de drempel is het een sleepgebaar. Tot
      // dat moment blijft de pane dicht, zodat een trillende hand op de rail
      // geen halve zijnav opentrekt.
      if (!sleep.geopend && x - sleep.start < RAIL_SLEEP_DREMPEL) return;
      if (!sleep.geopend) { sleep.geopend = true; zetOpen(true); }
    }
    sleep.w = zetTreeBreedte(x);
  }
  // Loslaten bewaart de uitkomst — en alleen dán: een gebaar zonder beweging is
  // een klik (op de rail) of een halve dubbelklik (op de rand) en mag de
  // breedte niet met een paar pixels verzetten.
  function eindigSleep() {
    if (!sleep) return;
    const w = sleep.w;
    sleep = null;
    if (w) prefSet('tree.w', w);
  }
  // Escape breekt het gebaar af: de stand van vóór de sleep komt terug en er
  // wordt niets bewaard. Trok het gebaar de pane aan de rail open, dan gaat ook
  // dát terug — anders laat een afgebroken sleep alsnog de helft van zijn werk
  // staan.
  function breekSleepAf() {
    if (!sleep) return;
    const { startW, opRail, geopend } = sleep;
    sleep = null;
    zetTreeBreedte(startW);
    if (opRail && geopend) zetOpen(false);
  }

  // --- De Escape-laag -------------------------------------------------------
  function opToets(e: KeyboardEvent) {
    // Alleen als de pane openstaat: anders zou een Escape die voor iets anders
    // bedoeld is (of gewoon een reflex) de voorkeur onnodig overschrijven.
    if (e.key !== 'Escape' || !(open() && heeftInhoud())) return;
    const a = document.activeElement;
    // Staat de focus in het FILTERVELD, en staat er iets in? Dan leegt deze
    // Escape alleen het filter; de pane blijft open. Pas een TWEEDE Escape valt
    // door naar het gewone gedrag hieronder. Zonder deze tussenstap raakt wie
    // net een filter intikte zijn typwerk kwijt zodra hij de pane per ongeluk
    // dichttoetst.
    if (filterVeld && a === filterVeld && vraag()) {
      setQuery('');
      // Deze Escape is nu VOLLEDIG verbruikt door het filter en mag geen andere
      // document-brede Escape-handler meer bereiken. stopPropagation helpt daar
      // niet: dat voorkomt propagatie naar ANDERE knopen, niet dat overige
      // listeners op HETZELFDE knooppunt (document) nog draaien.
      if (e.preventDefault) e.preventDefault();
      if (e.stopImmediatePropagation) e.stopImmediatePropagation();
      else if (e.stopPropagation) e.stopPropagation();
      return;
    }
    // Escape is per definitie het toetsenbord. Stond de focus IN de pane, dan
    // verdwijnt hij daarmee: die hoort mee naar de rail. Stond hij elders in het
    // document, dan mag de zijnav hem niet naar zich toe trekken.
    const binnen = !!(paneel && a && paneel.contains(a));
    zetOpen(false, { focusVolgt: binnen });
  }

  // Escape tijdens een lopende breedte-sleep breekt die sleep af, en houdt de
  // toets weg bij de ANDERE Escape-handlers (de zijnav-laag hieronder, het
  // invulling-paneel, het dimensiemenu): één toetsaanslag hoort één ding af te
  // breken, niet ook nog de zijnav dicht te klappen.
  //
  // IN DE CAPTURE-FASE, zoals de sleep-Escape van de bevroren viewer
  // (viewer-bevroren/assets/doc.js, wireKnoopSleep ~11117) — en als EERSTE geregistreerd
  // van de twee. Capture draait vóór alles wat op het pad naar het doel ligt;
  // staat het document zélf als doel (zoals in de tests), dan telt de
  // registratievolgorde, en dan wint deze omdat hij er eerder staat. De guard
  // (`!sleep`) houdt hem smal: buiten een lopende sleep raakt hij geen enkele
  // Escape aan.
  function opSleepToets(e: KeyboardEvent) {
    if (e.key !== 'Escape' || !sleep) return;
    if (e.preventDefault) e.preventDefault();
    if (e.stopImmediatePropagation) e.stopImmediatePropagation();
    else if (e.stopPropagation) e.stopPropagation();
    breekSleepAf();
  }

  if (typeof document !== 'undefined' && document.addEventListener) {
    document.addEventListener('keydown', opSleepToets, true);
    document.addEventListener('keydown', opToets);
    // Slepen loopt op het document: de muis komt tijdens een sleep bijna altijd
    // van de smalle greep af.
    document.addEventListener('pointermove', beweegSleep as EventListener);
    document.addEventListener('pointerup', eindigSleep);
    document.addEventListener('pointercancel', eindigSleep);
    onCleanup(() => {
      document.removeEventListener('keydown', opSleepToets, true);
      document.removeEventListener('keydown', opToets);
      document.removeEventListener('pointermove', beweegSleep as EventListener);
      document.removeEventListener('pointerup', eindigSleep);
      document.removeEventListener('pointercancel', eindigSleep);
    });
  }

  function kies(id: string) {
    // De groepsknopen (__loose-agreements__, __artifacts__) zijn geen IRI's:
    // die klappen alleen open en dicht via hun driehoekje.
    if (!id || id.startsWith('__')) return;
    props.onSpring(id);
  }

  return (
    <>
      <nav
        class="doc-tree"
        id="doc-tree"
        ref={paneel}
        hidden={!heeftInhoud()}
        aria-label={tekst('tree.aria')}
      >
        <div class="tree-head">
          <div class="tree-head-row">
            <span class="tree-title">{tekst('tree.title')}</span>
            {/* aria-expanded (+ aria-controls), niet aria-pressed: de knop toont
                en verbergt een regio. */}
            <button
              class="tree-close"
              type="button"
              ref={sluitKnop}
              aria-controls="doc-tree"
              aria-expanded={open()}
              aria-label={tekst('tree.close')}
              title={tekst('tree.close')}
              onClick={(e) => zetOpen(false, { focusVolgt: isToetsKlik(e) })}
            >«</button>
          </div>
          <Filter
            query={query()}
            zetQuery={setQuery}
            getoond={getoond()}
            totaal={totaal()}
            ref={(el) => { filterVeld = el; }}
          />
        </div>
        <Show when={open() && heeftInhoud()}>
          <Boom
            nav={getoondeNav()}
            negeerDicht={!!vraag()}
            selected={weergave.policyScope || weergave.setScope || null}
            onSelect={kies}
          />
        </Show>
        <div
          class="tree-resizer"
          onPointerDown={(e) => startSleep(e, { vanaf: e.currentTarget, opRail: false })}
          // Dubbelklikken op de rand klapt in en uit — hetzelfde gebaar als op
          // de rand van een kolom in een verkenner.
          onDblClick={(e) => { e.preventDefault(); zetOpen(!open()); }}
        />
      </nav>
      {/* De rail is de enige zichtbare weg terug uit de dichte stand: hij staat
          er altijd als er beleid is en de pane dicht is. Het woord staat in een
          eigen span — de chevron ervoor is een ::before, en die hoort niet in
          dezelfde (verticale) tekststroom te vallen. */}
      <button
        class="tree-rail"
        id="tree-rail"
        type="button"
        ref={railKnop}
        hidden={open() || !heeftInhoud()}
        aria-controls="doc-tree"
        aria-expanded={open()}
        aria-label={tekst('tree.railTip')}
        title={tekst('tree.railTip')}
        onClick={(e) => {
          // Een sleepgebaar aan de rail heeft de pane al geopend (en op breedte
          // gezet); de klik die er in de browser achteraan komt mag daar niet
          // overheen renderen.
          if (open()) return;
          zetOpen(true, { focusVolgt: isToetsKlik(e) });
        }}
        onPointerDown={(e) => startSleep(e, { vanaf: e.currentTarget, opRail: true })}
      >
        <span class="rail-label">{tekst('tree.title')}</span>
      </button>
    </>
  );
}
