// WORTELCOMPONENT: de chrome van de leesviewer.
//
// De schil zet drie dingen neer — een kop met de taalkiezer, de hoofdkolom voor
// de standen, en de statusregel — en koppelt de twee stores aan elkaar: de
// bronnen uit de URL (weergave) gaan naar de corpusstore, en het taalattribuut
// van het document volgt de gekozen taal (applyChrome deed dat in de oude
// viewer). De id's zijn nieuw; de twintig id's van doc.html zijn bewust NIET
// overgenomen, want de nieuwe app rendert haar DOM zelf.
//
// De hoofdkolom draagt het document (de kaartenlijst) en de SPARQL-schil
// daaromheen. De zijnav staat er los naast: hij
// hangt als vaste kolom (position: fixed) naast de schil en schuift de pagina
// in via een klasse op de body — daarom staat hij hier vóór de kop, en niet in
// de hoofdkolom.
import { createEffect, lazy, on, onCleanup, onMount, Show, untrack } from 'solid-js';
import { VERSIE } from './versie.js';
import { bronnen, endpointIsBron, herbouw, laadCorpus } from './stores/corpus.js';
import { onthul, spring, tekst, weergave, zetMelding } from './stores/weergave.js';
import { Bewerkchrome, Bewerkknop, bronpaneelBewerkt } from './ui/app/bewerkstand.jsx';
import { bronnenOpen, Bronnenknop, Bronnenpaneel, zetBronnenOpen } from './ui/app/bronnen.jsx';
import { startBronbeheer } from './stores/bronbeheer.js';
import { InvullingPaneel, springNaarRef as springInPaneel } from './ui/kaart/invulling.jsx';
import { Statusregel } from './ui/app/status.jsx';
import { Taalkiezer } from './ui/app/taalkiezer.jsx';
import { Secties } from './ui/lijst/secties.jsx';
import { Zijnav } from './ui/zijnav/zijnav.jsx';

// DE SPARQL-SCHIL IS EEN EIGEN CHUNK (golf 3.1, codesplitsing per stand).
//
// Hij is geen onderdeel van het LEZEN: wie een document opent ziet de
// kaartenlijst, en pas een endpoint-bron brengt hem in beeld. Statisch
// importeren trok zijn code en zijn CSS de instapchunk in, voor elke lezer die
// hem nooit aanzet.
//
// HIER STOND OOK DE VERKENNER, om dezelfde reden lazy. Hij is op 16 sep 2026
// gesloopt (eigenaarsbesluit), met de `?verken=`-route, het ⌕ en de
// pushState-geschiedenis eromheen. Wat er nu over is, is één stand plus zijn
// schil — en daarmee is dit geen standen-switch meer maar een schil-switch.
//
// WAAROM `lazy()` EN GEEN `<Show>` MET EEN HANDMATIGE IMPORT: Solid's `lazy`
// koppelt het laden aan het MONTEREN, en dat is precies het moment waarop de
// `<Show>` hieronder van tak wisselt. Een eigen `createResource` zou hetzelfde
// doen met meer code en één extra faalpad.
//
// GEEN `<Suspense>` eromheen, met opzet. De wissel is een lokale gebeurtenis;
// een Suspense-grens zou de hele hoofdkolom laten knipperen terwijl er alleen
// een chunk van een paar kB onderweg is. Zonder grens houdt Solid de vorige
// inhoud staan tot de nieuwe er is.
const SparqlStand = lazy(async () => ({
  default: (await import('./ui/sparql/sparql.jsx')).SparqlStand,
}));

/** Springen naar een kaart: `spring()` uit de weergavestore opent eerst de
 *  sectie (en wist zo nodig een filter dat de kaart verbergt), laat de kaart
 *  bestaan en scrolt er dán pas naartoe. Het `data-ref`-contract (verkenning
 *  knoop 10) is waar hij op landt — vanuit de zijnav en vanuit een
 *  kruisverwijzing op een kaart. */
export async function springNaarRef(ref: string): Promise<void> {
  zetMelding(null);
  const geland = await spring(ref, { smooth: true });
  // NIET ELKE KNOOP HEEFT EEN KAART — de tak "Machine-uitvoerbaar beleid" in de
  // zijnav bijvoorbeeld. De bevroren viewer meldt dat op de statusregel
  // (doc.js r.10798-10803); zonder die melding klikt de lezer in het niets.
  if (!geland) zetMelding('sprong.notInDoc');
}

/** De sprong vanuit het INVULLING-PANEEL. Bewust niet `spring` zelf, om twee
 *  redenen die allebei stil zouden mislukken:
 *
 *  1. `onSpring` geeft `(ref, scope)` door en `spring` leest zijn tweede
 *     argument als een OPTIE-object. De scope zou dus verdwijnen — en met hem
 *     de voorrang van de kaart waar het paneel op staat (`kaartVanScope` in
 *     invulling.tsx). Een gedeelde plicht landt dan in de eerste de beste kaart
 *     in plaats van in de juiste; dat is precies wat de side-by-side van taak 8b
 *     als "identiek" heeft afgetekend.
 *  2. `spring` levert een Promise, en die is altijd truthy — het paneel zou een
 *     mislukte sprong voor geslaagd aanzien.
 *
 *  Daarom samengesteld: de LIJST onthult (sectie open, filter zo nodig weg,
 *  kaart bestaat), en daarna doet het PANEEL zijn eigen sprong, met scope, met
 *  hover-opruiming en met de puls. De tik ertussen is nodig omdat een onthuller
 *  signalen zet: de kaart bestaat pas ná de volgende taak. */
export function springUitPaneel(ref: string, scope: string | null): void {
  onthul(ref);
  setTimeout(() => { springInPaneel(ref, scope); }, 0);
}

// DE BRONNENLAAG aanhaken, vóór de eerste lading: een bron met een lokale
// OPFS-kopie komt uit die kopie en de werkbestanden van deze browser komen
// erbij (dt3, registreerBronVoorbewerking). Op moduleniveau en niet in een
// effect, want de eerste `laadCorpus` loopt al bij de eerste render — een
// registratie erna zou de eerste lading nog zonder overlay laten.
startBronbeheer();

export function App() {
  // DE GEMETEN HOOGTE VAN DE MEESCHUIVENDE KOPBALK, als `--kop-h` op <html>.
  //
  // De balk is sticky (app.css) en dekt dus de bovenkant van het scrollvenster
  // af. Wie daaronder wil landen moet weten hoe hoog hij is, en die hoogte is
  // GEEN constante: de kop flex-wrapt op smal scherm naar twee of drie regels,
  // de bewerkknop komt er in de bewerkstand bij, en de lettermaat van de lezer
  // telt mee. Een getal in de CSS zou op precies één viewport kloppen.
  //
  // Daarom meten we hem, en schrijven we hem één keer weg als variabele die
  // twee lezers heeft: `html { scroll-padding-top }` (elke scrollIntoView en
  // elke #-sprong) en `topbarOffset()` in ui/gedeeld/meescroll.ts (de
  // meescroll, die zelf rekent en dus niet via de scroll-padding loopt).
  //
  // ResizeObserver en geen resize-luisteraar op window: de wrap slaat ook om
  // zonder dat het venster verandert (het bronnenpaneel opent en versmalt de
  // kop, de bewerkstand voegt een knop toe). Ontbreekt hij, dan blijft het bij
  // de eerste meting — nog altijd beter dan nul.
  onMount(() => {
    if (typeof document === 'undefined') return;
    const kop = document.querySelector('.app-kop') as HTMLElement | null;
    if (!kop || typeof kop.getBoundingClientRect !== 'function') return;
    let vorige = -1;
    const meet = () => {
      // Afronden naar boven: een halve pixel te weinig laat de bovenrand van
      // het doel nog net onder de balk vallen.
      const h = Math.ceil(kop.getBoundingClientRect().height);
      if (h === vorige) return;          // geen stijlschrijfbeurt zonder nieuws
      vorige = h;
      document.documentElement.style.setProperty('--kop-h', `${h}px`);
    };
    meet();
    if (typeof ResizeObserver !== 'function') return;
    const ro = new ResizeObserver(meet);
    ro.observe(kop);
    onCleanup(() => { ro.disconnect(); });
  });

  // DE LEGE START (eigenaarsbesluit 9 sep 2026: "echt leeg natuurlijk.
  // demobronnen moeten eruit"). Wie de app zonder parameters opent krijgt geen
  // corpus meer, en dan is een leeg document zonder uitleg een doodlopende
  // pagina. Het bronnenpaneel gaat daarom open staan: daar staat de lege-
  // staat-melding, het voorbeeldlinkje en het veld waarin je je eigen bron zet.
  //
  // ALLEEN BIJ EEN ECHT KALE URL. Wie `?src=` of een endpoint meegaf heeft om
  // een document gevraagd en hoort dat te zien, ook als de lading mislukt —
  // een paneel dat dan ongevraagd openklapt zou zijn leeskolom versmallen op
  // het moment dat hij naar een foutmelding zit te kijken.
  //
  // EN DE CURSOR IN HET TOEVOEGVELD: dit is het enige moment waarop er precies
  // één zinnige handeling is. Focus stelen bij een lading die wél iets oplevert
  // zou de lezer uit zijn document trekken; hier is er geen document.
  // WIE HET PANEEL OPENDEED. Alleen wat de APP zelf aanbood, sluit de app ook
  // zelf weer; wat de lezer openklapte blijft van hem.
  let vanzelfOpen = false;
  onMount(() => {
    const kaal = !weergave.src.length && !weergave.ttl.length && !weergave.sparql
      && !weergave.policyScope && !weergave.setScope;
    if (!kaal) return;
    vanzelfOpen = true;
    zetBronnenOpen(true);
    if (typeof document === 'undefined') return;
    // Ná de eerste render van het paneel: het veld bestaat pas als hij open is.
    queueMicrotask(() => {
      (document.getElementById('src-add-url') as HTMLElement | null)?.focus();
    });
  });

  // …EN GAAT WEER DICHT ZODRA DE LEGE START VOORBIJ IS.
  //
  // DE BREEDTE-REGRESSIE (eigenaarsbevinding 9 sep 2026, letterlijk: "Hij
  // gebruikt ineens niet meer de breedte van het hele scherm"). Het paneel houdt
  // een kolom van 320px vrij zolang het openstaat, en dat hoort ook — je leest
  // ernaast door. Maar bij de lege start ging het VANZELF open, en wie daar zijn
  // eerste bron in het veld zette, hield een document van 680px over naast een
  // paneel met één regel erin. De hulp bleef staan nadat ze geholpen had.
  //
  // De voorwaarde is precies omgekeerd aan die van het openen: het paneel ging
  // open omdat er niets anders te doen was, dus gaat het dicht zodra dat wél zo
  // is. Eén keer — daarna is `vanzelfOpen` op en beslist alleen de lezer nog.
  createEffect(() => {
    // Sluit de lezer hem zelf, dan geeft hij de hulp terug: vanaf dat moment is
    // elke opening van hem, en raakt deze regel hem niet meer aan.
    if (!bronnenOpen()) { vanzelfOpen = false; return; }
    if (!vanzelfOpen || !bronnen().length) return;
    vanzelfOpen = false;
    // DE FOCUS MEE. Hij staat op dit moment in het toevoegveld (daar kwam de
    // bron vandaan) en dat veld verdwijnt; zonder dit valt hij terug op <body>.
    // De hoofdkolom is waar de lezer nu hoort te zijn: daar staat wat hij zojuist
    // laadde. `#app-hoofd` draagt daarvoor al `tabindex="-1"`.
    const paneel = typeof document === 'undefined' ? null
      : document.getElementById('bronnen-paneel');
    const binnen = !!(paneel && document.activeElement && paneel.contains(document.activeElement));
    zetBronnenOpen(false);
    if (binnen) (document.getElementById('app-hoofd') as HTMLElement | null)?.focus();
  });

  // Taal van het document (schermlezers, hyphenation) volgt de keuze.
  createEffect(() => {
    document.documentElement.setAttribute('lang', weergave.lang);
  });

  // Bronnen uit de adresbalk. ?src= en ?ttl= gaan GESCHEIDEN naar de store: ?src=
  // is de generieke ingang (een waarde kan een bestand of een endpoint zijn en
  // wordt gedetecteerd), ?ttl= is de legacy-alias die altijd een bestand is.
  // ?sparql= (endpoint) reist als vanouds apart. Reactief, zodat een latere
  // bronwijziging (bronnenpaneel) dezelfde weg loopt.
  //
  // ALLEEN de bronnen zijn hier reactief. Taal en ?set= reizen wel mee naar de
  // modelbouw (de worker heeft ze nodig), maar untracked: een taalwissel mag
  // het corpus niet opnieuw over het netwerk halen — die gaat via herbouw()
  // hieronder, en een scope-wissel krijgt in taak 3 zijn eigen goedkope pad.
  //
  // `policyScope` en `excludeGraphs` moeten mee sinds taak 8a: zonder
  // policyScope blijft de deeplink-route (?policy= zonder bronnen) onbereikbaar,
  // en excludeGraphs hoort bij de endpoint-queries.
  createEffect(() => {
    const src = [...weergave.src];
    const ttl = [...weergave.ttl];
    const sparql = weergave.sparql ?? undefined;
    // Een nieuwe lading wist de vluchtige melding: zij hoorde bij de vorige
    // weergave. Hier en niet in de corpusstore, want het is een uitspraak van
    // de SCHIL over haar statusregel (bevinding NB-2).
    zetMelding(null);
    untrack(() => laadCorpus({
      src, ttl, sparql, policyScope: weergave.policyScope, setScope: weergave.setScope,
      lang: weergave.lang, excludeGraphs: weergave.excludeGraphs,
    }));
  });

  // TAALWISSEL: het model is taalgebakken (labels, rolwoorden, titels komen uit
  // de graaf via pickLabel), dus een wissel moet het model opnieuw bouwen —
  // exact wat switchLang in de bevroren viewer doet. Uit de BEWAARDE graaf, dus
  // zonder fetch en zonder her-parse. `defer` houdt de eerste render vrij: daar
  // heeft de lading het model al in de juiste taal gebouwd.
  createEffect(on(() => weergave.lang, () => {
    zetMelding(null);                       // idem bij een taalwissel (NB-2)
    void herbouw({ lang: weergave.lang });
  }, { defer: true }));

  return (
    <>
      {/* Eerste focusbare element: wie met het toetsenbord binnenkomt hoeft
          niet langs de chrome te tabben om bij het document te zijn. */}
      <a class="skip-link" href="#app-hoofd">{tekst('tree.skip')}</a>
      <Zijnav onSpring={springNaarRef} />
      <header class="app-kop" id="app-kop">
        <div class="merk">
          <span class="logo">ODRL Visualizer</span>
          {/* GEEN PROFIELNAAM IN DE KOP (eigenaarsbesluit 15 sep 2026,
              letterlijk: "in ODRL Vis het profiel weglaten"). Hier stond de
              naam van één profiel als vaste ondertitel. De viewer toont elke
              ODRL-bron; een ondertitel die één profiel noemt belooft iets
              smallers dan de app doet, en zet de lezer met een generieke bron
              op het verkeerde been. Het profielVOCABULAIRE van de bundel
              blijft wél meeladen — dat geeft labels en belooft niets. De naam
              staat sinds 16 sep 2026 op de STATUSREGEL (`profielNaam` in
              model/profiel.js), waar hij een gegeven is en geen merk. */}
          <span class="versie" id="app-versie">{VERSIE}</span>
        </div>
        {/* De kop verdeelt met space-between; knop en taalkiezer horen als één
            blok rechts te staan, niet elk aan een eigen kant. */}
        <div class="kop-acties">
          {/* DE BEWERKGRENS. De knop is chrome en staat er altijd; wat erachter
              hangt (de mutatiekern, de serialisatielaag, de velden) komt pas
              over de lijn bij de eerste klik — spec §1, en de reden staat
              voluit in ui/app/bewerkstand.tsx. Vóór de bronnenknop, want de
              bewerkstand is wat het bronnenpaneel van vorm doet veranderen. */}
          <Bewerkknop />
          <Bronnenknop />
          <Taalkiezer />
        </div>
      </header>
      {/* De balk van de bewerkstand hoort tussen de kop en het bronnenpaneel:
          hij gaat over wat je met dit document doet, het paneel over waar het
          vandaan komt. In de leesstand rendert hij niets. */}
      <Bewerkchrome />
      {/* HET BRONNENPANEEL staat sinds 9 sep 2026 als vaste kolom RECHTS
          (eigenaarsbesluit: "Sources is logischer als een pane aan de
          rechterzijde dan aan de top"). In de DOM blijft hij hier, tussen de
          kop en de hoofdkolom: dat is de tabvolgorde die hoort bij de knop in
          de kop die hem opent. Hij duwt de leeskolom opzij in plaats van er
          overheen te liggen — net als het invulling-paneel aan diezelfde kant;
          de marge zet ui/app/bronnen.css op de body. */}
      <Bronnenpaneel bewerken={bronpaneelBewerkt} />
      <main class="app-hoofd" id="app-hoofd" tabindex="-1">
        {/* De SPARQL-stand is geen tweede stand maar een SCHIL rond diezelfde
            documentweergave (skelet, endpoint-status, fasen). Hier stond tot 16
            sep 2026 een <Show> die de verkenner-stand ervoor zette; met de
            sloop van de verkenner is de documentweergave het enige wat de
            hoofdkolom nog draagt. */}
        {/* DE ENDPOINT-CHROME HANGT AAN DE STORE, niet alleen aan de
            URL-parameter. Sinds een `?src=`-waarde een endpoint kan BLIJKEN
            (golf C) is `weergave.sparql` niet meer de hele waarheid: zo'n
            lading kreeg wel de endpoint-DATA maar niet het fase-skelet, geen
            `data-lijstfase`, en — de scherpe — geen endpoint-foutmelding met
            URL en CORS-hint, alleen een halve zin op de statusregel (bevinding
            I-2 van de review). `endpointIsBron()` zegt wat `weergave.sparql`
            niet kan zeggen: dat het endpoint de BRON van deze lading is. In het
            gemengde geval (bestand én endpoint in dezelfde ?src=-lijst) is het
            bestand de bron en blijft de gewone documentweergave staan. */}
        <Show when={weergave.sparql || endpointIsBron()} fallback={<Secties />}>
          <SparqlStand><Secties /></SparqlStand>
        </Show>
      </main>
      <Statusregel />
      {/* Het paneel is `position: fixed` en zet `body.panel-open`: het hoort
          buiten <main>, als laatste kind van het fragment. */}
      <InvullingPaneel onSpring={springUitPaneel} />
    </>
  );
}
