// DE BODY VAN EEN KAART: kenmerk, beschrijving, partijen, datums en herkomst.
//
// Gedragsbron: setCardBody/requestCardBody, fillOfferSection en
// fillAgreementPage in de bevroren viewer, plus de veldbouwers ref(),
// provRefNode/derivedFromValue, requestValue, asksForNodes, requestSubtitle en
// versionLine. Elke kaartsoort heeft haar eigen RIJENLIJST — dat is het enige
// wat de drie bodys onderscheidt; de omhulling is identiek.
//
// VIER BETEKENISSEN VAN ÉÉN PREDICAAT (note §4): prov:wasDerivedFrom draagt de
// aanbod-invulling ("Vult aanbod in"), het verzoek (de Verzoek-regel), de
// aanvraag van een verzoek ("vraagt … aan") én de gewone herkomst ("Afgeleid
// van"). Elke betekenis heeft haar eigen regel; de doelwitten van de eerste
// drie worden daarom uit "Afgeleid van" gefilterd, precies als in de viewer.
//
// WAT HIER (NOG) NIET IN ZIT: de uitleg-tooltips (de graaf zit achter de
// worker-grens) en alle bewerk-affordances (deeltraject 3).
//
// HET ⌕ EN DE SPRONGEN staan er sinds de gaten-ronde wél in (bevindingen C-1
// en I-3): elke verwezen knoop draagt haar verken-knop, de verzoekregel en de
// "beslist in"-regel zijn weer een SPRONG binnen de pagina in plaats van een
// herlading naar `?policy=`.
import { For, Show } from 'solid-js';
import type { JSX } from 'solid-js';
import {
  agreementsByRequest, curie, dayDate, isGraphSubject, policyAssignee,
} from '../../model/parse.js';
import { graaf, graafVersie, model } from '../../stores/corpus.js';
import { spring, tekst } from '../../stores/weergave.js';
import { PRED, Veld } from '../bewerk/haken.jsx';
import { Kv, TermKop } from '../gedeeld/kop.jsx';
import type { KvRij } from '../gedeeld/kop.jsx';
import { bewerklaagActief, focusAdres } from '../gedeeld/bewerkhaak.jsx';
import { Collectie } from './collectie.jsx';
import type { CollectieKnoop } from './collectie.jsx';
import { KnoopKeten, KnoopVouw } from './formulier.jsx';
import { dektKnoop } from './formulier-model.js';
import { Terugverwijzingen } from './terugverwijzingen.jsx';
import { LangeTekst } from '../gedeeld/langetekst.jsx';
import { veiligeHref } from '../gedeeld/veilige-link.js';
import type { Kaartsoort } from '../gedeeld/chip.jsx';
import type { Partij, Policy, Versie, Verwijzing } from './kaart.jsx';

/** Een ?policy=-deeplink op de huidige zoekstring — dezelfde vorm als in de
 *  bevroren viewer, zodat een gedeelde link identiek blijft. */
function policyHref(iri: string): string {
  const u = new URLSearchParams(typeof location === 'undefined' ? '' : location.search);
  u.set('policy', iri);
  return '?' + u.toString();
}

// --- DE KRUISVERWIJZING NAAR EEN ANDERE KAART (bevinding I-3) ----------------
// De keten aanbod → verzoek → overeenkomst loopt over drie top-secties, dus de
// verwijzingen ertussen moeten een SPRONG zijn en geen paginawissel. Dit is een
// gewone `<a href="?policy=…">` — middelklik, "openen in nieuw tabblad" en
// kopiëren blijven dus werken, en zonder JavaScript landt de lezer alsnog op de
// detailpagina — maar bij een gewone klik navigeert hij NIET: `spring()` opent
// de omvattende sectie, laat de kaart renderen, klapt hem open, scrolt ernaartoe
// en laat hem oplichten. Kan de pagina de kaart niet vinden (?policy=-scope, of
// nog niet geladen in ?sparql=-modus), dan volgt de link alsnog.
//
// Gemeten vóór deze fix, één klik op "beslist in": oud bleef in de pagina
// (scrollY 0 → 5.858, URL onveranderd), nieuw herlaadde naar `?policy=<iri>` en
// snoeide het document tot die ene policy — de lezer raakte zijn plek én zijn
// corpusbeeld kwijt. Gedragsbron: `jumpAnchor`/`jumpLink` (doc.js r.849-873).
export function KaartSprong(props: {
  iri: string; titel?: string | null; class?: string; children?: JSX.Element;
}): JSX.Element {
  return (
    <a
      href={policyHref(props.iri)}
      class={props.class ? 'card-jump ' + props.class : 'card-jump'}
      title={props.titel || undefined}
      onClick={(e) => {
        // Modifier-klik (nieuw tabblad/venster) en middelklik blijven van de
        // browser; alleen de gewone linkerklik wordt een sprong.
        if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || e.button) return;
        e.preventDefault();
        const href = (e.currentTarget as HTMLAnchorElement).href;
        Promise.resolve(spring(props.iri, { smooth: true })).then((ok) => {
          if (!ok && typeof location !== 'undefined') location.href = href;
        }).catch(() => { /* de link blijft staan */ });
      }}
    >{props.children}</a>
  );
}

/** Een verwezen knoop: naam, curie, en het ⌕ naar diezelfde knoop in de
 *  verkenner (`ref()` in de bevroren viewer, doc.js r.3603). */
export function Ref(props: { agent?: Partij | null }): JSX.Element {
  // De naam alleen als hij iets TOEVOEGT: is het label gelijk aan de curie,
  // dan zou de rij hem twee keer tonen.
  const naam = () => {
    const a = props.agent;
    return a && a.label && a.label !== a.curie ? a.label : null;
  };
  // De naam-tag. `data-iri` is het adres waarop een sprong deze partij in de
  // weergave terugvindt (revealInUi).
  const tag = (a: Partij) => (iri: string | null) => (
    <span data-iri={iri || undefined}>
      <Show when={naam()}>{(l) => <>{l()}{' '}</>}</Show>
      <span class="mono muted">{iri ? a.curie : ''}</span>
      {/* Partijen (en andere verwezen knopen) zijn verkenbaar. Een ANONIEME
          collectie heeft geen IRI maar wel een blanke term — en die levert
          geen adres, dus daar valt de knop vanzelf weg. */}
    </span>
  );
  // DE NAAM-TAG VAN EEN COLLECTIEKAART, met haar veldroute (fixronde 1, brief
  // deel 3: "label/titel bewerkbaar"; review-sloteditor §2c mat op de echte
  // vlierdam-collectie `{"naamHeeftBewerkAffordance": false}`).
  //
  // Waarom een EIGEN tag naast `tag()` hierboven, en niet dezelfde met een vlag:
  // de twee zijn verschillende dingen. `tag()` is de weergave van een VERWIJZING
  // — de knoop woont ergens anders, en zijn naam hoort daar bewerkt te worden.
  // Deze tag is de KOP VAN EEN KAART: de collectie staat hier met haar soort,
  // haar bron en haar afbakening, en dát is de plek waar de eigenaar vroeg
  // waarom er niets te bewerken viel. Dezelfde veldroute als de kaarttitel en de
  // regelnaam (`Veld` met `PRED.TITEL`), dus geen tweede mechanisme; in de
  // kijkstand rendert `Veld` letterlijk zijn kind en verandert er geen pixel.
  //
  // `waarde` is de GETOONDE naam en niet alleen het eigen label: met een lege
  // waarde zou een collectie die haar naam aan haar curie ontleent in de
  // bewerkstand naamloos opengaan. Een save die niets verandert wordt
  // overgeslagen (`TekstVeld`), dus dit materialiseert geen titel die er niet
  // stond.
  //
  // SINDS DE HINT ERBIJ STAAT (9 sep 2026) doet die getoonde naam nog precies
  // één ding, en dat is het ding waarvoor hij hier stond: de GESLOTEN stand
  // toont hem (`leeg` in `TekstVeld`), zodat de kaart niet naamloos oogt. Het
  // OPEN invoerveld start leeg met de hint — want de getoonde naam van een
  // verse groep is een AFLEIDING (de localName "groep"), en die als ingevulde
  // waarde in een invoerveld zetten is precies wat de eigenaar tweemaal meldde.
  const collTag = (a: Partij) => (iri: string | null) => (
    <span data-iri={iri || undefined}>
      <Veld spec={{
        term: iri || (a as { term?: unknown }).term,
        soort: 'tekst',
        preds: PRED.TITEL,
        waarde: naam() ?? '',
        // DE HINT EN HET FOCUSADRES VAN EEN VERSE GROEP (9 sep 2026, de
        // aanmaakroute). Sinds het afnemer-veld een `odrl:PartyCollection` kan
        // MINTEN, is deze kop de plek waar zo'n groep zijn naam krijgt: de
        // mint zet het adres van de nieuwe knoop in het focusverzoek, en dit
        // veld herkent zich erin en opent zich met de cursor erin. Zonder
        // `focusSleutel` landt de lezer op een naamloze kaart zonder te zien
        // waar hij moet typen; zonder `hint` staat dat veld leeg zonder te
        // zeggen wat erin hoort. Zelfde mechaniek als bij de regelnaam
        // (`regels.tsx`) — een adres, geen verwijzing.
        hint: tekst('edit.hintGroepNaam'),
        focusSleutel: focusAdres(iri || (a as { term?: unknown }).term),
      }}
      >
        <Show when={naam()}>{(l) => <>{l()}{' '}</>}</Show>
      </Veld>
      <span class="mono muted">{iri ? a.curie : ''}</span>
      {/* EEN BLANKE GROEP KAN HIER EEN NAAM KRIJGEN (eigenaarsrichting 9 sep
          2026). `addPartyCollection` mint een BENOEMDE groep zodra het subject er
          een heeft en valt anders terug op een blanke knoop — en juist die groep
          is niet te delen met een tweede regel of een tweede beleid, want er is
          niets om naar te wijzen. Dezelfde chip als op de kaartkop, met dezelfde
          mutatie (`benoemKnoop`); een BENOEMDE groep toont hier haar curie al en
          krijgt er dus geen tweede weergave bij. */}
      <Show when={!iri && (a as { term?: unknown }).term}>
        <Veld spec={{
          term: (a as { term?: unknown }).term,
          soort: 'iri',
          preds: [],
          vorm: 'knoopIri',
          iri: null,
        }}
        />
      </Show>
    </span>
  );
  // Een odrl:PartyCollection is meer dan een naam: zij draagt haar leden en/of
  // de voorwaarde waaraan een partij moet voldoen (bevinding I-4). Een gewone
  // partij blijft precies wat zij was.
  //
  // `collKind` TELT MEE (9 sep 2026, de aanmaakroute). Deze toets keek naar wat
  // een collectie DRAAGT — een intensie of opgesomde leden — en niet naar wat
  // zij IS. Een verse `odrl:PartyCollection` draagt geen van beide: zij is
  // getypeerd en verder leeg. Zonder deze tak kwam zij dus als GEWONE partij op
  // het scherm (de kale `tag`), zonder soortchip, zonder collectiekaart en
  // zonder de "Afbakening"-sectie waar haar eerste refinement moet ontstaan —
  // de mint leverde dan een groep op die nergens als groep te zien was.
  //
  // Dezelfde lezing als `isCollectie` in `collectie.tsx`, die de TARGET-kant al
  // zo doet; dat de partijkant het anders deed was een verschil zonder reden.
  // De leeswinst geldt ook zonder bewerkstand: een getypeerde lege groep wordt
  // nu als groep getoond in plaats van als partij die zij niet is.
  const collectie = () => {
    const a = props.agent as (Partij & CollectieKnoop) | null | undefined;
    return a && (a.intension || (a.members || []).length || a.collKind) ? a : null;
  };
  return (
    <Show when={props.agent}>{(a) => (
      <Show when={collectie()} fallback={tag(a())(a().iri || null)}>{(c) => (
        <span class="party-coll"><Collectie desc={c()} tag={collTag(a())} /></span>
      )}</Show>
    )}</Show>
  );
}

/** Leesbaar label voor een herkomstverwijzing: URL-gecodeerde padsegmenten
 *  (besluit-PDF's) worden gedecodeerd getoond. */
export function refLabel(d: Verwijzing): string {
  let label = d.label || d.curie || d.iri;
  if (/%[0-9A-Fa-f]{2}/.test(label)) {
    try { label = decodeURIComponent(label); } catch { /* laat de tekst staan */ }
  }
  return label;
}

function isPolicy(iri: string): boolean {
  const m = model() as any;
  if (!m) return false;
  return [...m.sets, ...m.offers, ...m.agreements].some((p: Policy) => p.iri === iri);
}

/** Eén herkomst-/versieverwijzing. Externe http(s)-doelwitten die zelf geen
 *  policy in het model zijn, zijn beter af als échte link (nieuw tabblad);
 *  interne verwijzingen blijven tekst, en wijst de verwijzing naar een policy
 *  die we zélf kennen, dan is zij ook te ópenen. */
export function ProvRef(props: { d: Verwijzing }): JSX.Element {
  const extern = () => /^https?:/.test(props.d.iri) && !isPolicy(props.d.iri);
  const curieNaast = () => {
    const c = props.d.curie;
    return c && c !== refLabel(props.d) && !/^https?:/.test(c) ? c : null;
  };
  // Bij een EXTERNE link blijft het ⌕ alleen staan wanneer er ook echt triples
  // over die knoop bekend zijn — anders zou de verkenner op een lege pagina
  // uitkomen (doc.js r.3649). De graafversie meelezen houdt hem reactief: de
  // graaf komt op het worker-pad ná het model binnen.
  const inGraaf = () => {
    void graafVersie();
    const g = graaf();
    return !!g && isGraphSubject(g, props.d.iri);
  };
  return (
    <Show
      when={!extern()}
      fallback={(
        <span>
          <a href={props.d.iri} target="_blank" rel="noopener">{refLabel(props.d)}</a>
        </span>
      )}
    >
      <span>
        {/* Een gewone `?policy=`-link, precies als in de bevroren viewer
            (doc.js r.3665): dit is een HERKOMST-verwijzing naar een andere
            versie of een bronbesluit — een detailpagina, geen sprong binnen de
            keten. Alleen de drie ketenregels (verzoek, "vraagt … aan",
            "beslist in") zijn `card-jump`. */}
        <Show when={isPolicy(props.d.iri)} fallback={refLabel(props.d)}>
          <a href={policyHref(props.d.iri)}>{refLabel(props.d)}</a>
        </Show>
        <Show when={curieNaast()}>{(c) => <>{' '}<span class="mono muted">{c()}</span></>}</Show>
      </span>
    </Show>
  );
}

/** "Afgeleid van": verwijzingen met '; ' gescheiden — titels van wetten en
 *  besluiten bevatten zelf komma's.
 *
 *  `klasse` is de haak van de VINDPLAATS (`sourceLocationValue`, doc.js
 *  r.3697-3699): dezelfde lijst verwijzingen, maar in een eigen omhulsel met
 *  een eigen vorm — kleiner, gedempt en met de documentmarkering ervoor. De
 *  bevroren viewer zet die klasse op precies deze span, dus doen wij dat ook. */
export function ProvRefs(props: { lijst?: Verwijzing[] | null; klasse?: string }): JSX.Element {
  return (
    <Show when={(props.lijst || []).length}>
      <span class={props.klasse || undefined}>
        <For each={props.lijst}>{(d, i) => (
          <>{i() ? '; ' : ''}<ProvRef d={d} /></>
        )}</For>
      </span>
    </Show>
  );
}

/** "Vult aanbod in": de aanbiedingen die deze overeenkomst invult, elk als
 *  ?policy=-link naar zijn eigen pagina. */
function AanbodLinks(props: { iris?: string[] }): JSX.Element {
  const m = () => model() as any;
  const titel = (iri: string) => {
    const off = m() && m().offers.find((o: Policy) => o.iri === iri);
    return (off && off.title) || curie(iri);
  };
  return (
    <Show when={(props.iris || []).length}>
      <span>
        <For each={props.iris}>{(iri, i) => (
          <>{i() ? ', ' : ''}<a href={policyHref(iri)}>{titel(iri)}</a></>
        )}</For>
      </span>
    </Show>
  );
}

/** De Verzoek-regel op een overeenkomst: kenmerk · datum · indiener — dezelfde
 *  drie velden die de verzoek-kaart als subtitel toont, zodat je aan beide
 *  kanten van de sprong hetzelfde leest. */
function VerzoekRegel(props: { lijst?: Verwijzing[] | null }): JSX.Element {
  const items = () => (props.lijst || []).filter(Boolean) as any[];
  const stukken = (r: any): JSX.Element[] => {
    const uit: JSX.Element[] = [];
    if (r.identifier) uit.push(<span class="mono muted doc-ref">{r.identifier}</span>);
    const d = dayDate(r.issued);
    if (d) uit.push(<span class="muted">{d}</span>);
    if (r.requester && r.requester.label) uit.push(<span>{r.requester.label}</span>);
    // Geen enkel veld ingevuld: dan tenminste de naam, zodat de regel nooit
    // leeg oogt.
    if (!uit.length) uit.push(<span>{r.title || r.label || r.curie || r.iri}</span>);
    return uit;
  };
  return (
    <Show when={items().length}>
      <span>
        <For each={items()}>{(r, i) => (
          <>
            {i() ? '; ' : ''}
            <span class="req-line" title={tekst('request.title')}>
              {/* BEVINDING I-3. Alleen de IDENTIFICERENDE stukken gaan IN het
                  anker; de aanvraag-zin heeft zijn eigen link en mag niet in een
                  link genest raken (requestValue, doc.js r.3748-3760). */}
              <KaartSprong iri={r.iri} titel={tekst('jump.toRequest')}>
                <For each={stukken(r)}>{(s, j) => <>{j() ? ' · ' : ''}{s}</>}</For>
              </KaartSprong>
              {/* De STAART van de regel: vraagt dit verzoek een aanbod aan, dan
                  laat de overeenkomst in één regel zien waar de aanvraag om
                  ging. Gemeten vóór deze fix: `RA-2026-0312 · 12-03-2026 ·
                  Radio Alpha` waar de bevroren viewer `… · vraagt
                  Streaminglicentie … aan` zet. */}
              <Show when={((r.asksFor || []) as Verwijzing[]).filter((a) => a && a.iri).length}>
                {' · '}<VraagtAan lijst={r.asksFor} />
              </Show>
            </span>
          </>
        )}</For>
      </span>
    </Show>
  );
}

/** "vraagt <aanbod> aan" (note §4, Request→Offer). De zin komt uit de
 *  stringtabel; de naam moet als eigen element in die zin staan, dus wordt de
 *  vertaling om een sentinel gesplitst — dezelfde truc als in de viewer. */
const SLEUF = '\u0000';

export function VraagtAan(props: { lijst?: Verwijzing[] | null }): JSX.Element {
  const items = () => (props.lijst || []).filter((a) => a && a.iri);
  const m = () => model() as any;
  const heeftKaart = (iri: string) => !!(m() && m().offers.some((o: Policy) => o.iri === iri));
  const naam = (a: Verwijzing) => {
    const off = m() && m().offers.find((o: Policy) => o.iri === a.iri);
    return (off && off.title) || a.label || a.curie || a.iri;
  };
  const delen = () => tekst('askOffer.line', { offer: SLEUF }).split(SLEUF);
  return (
    <Show when={items().length}>
      <span class="asks-for-line">
        <For each={items()}>{(a, i) => (
          <>
            {i() ? '; ' : ''}
            <span class="asks-for" title={tekst('askOffer.title')}>
              <span>{delen()[0]}</span>
              {/* De naam is een LINK zolang het aanbod een eigen kaart heeft;
                  staat het niet in het model, dan blijft het gedempte tekst —
                  we verzinnen geen bestemming (asksForNode, doc.js r.3800). */}
              <Show
                when={heeftKaart(a.iri)}
                fallback={<span class="asks-offer">{naam(a)}</span>}
              >
                <a href={policyHref(a.iri)}>{naam(a)}</a>
              </Show>
              <Show when={delen()[1]}>{(na) => <span>{na()}</span>}</Show>
            </span>
          </>
        )}</For>
      </span>
    </Show>
  );
}

/** "beslist in <overeenkomst>": de OMGEKEERDE keten-link op een verzoek. De
 *  relatie staat in de data alleen aan de overeenkomst-kant (Agreement →
 *  prov:wasDerivedFrom → Request); agreementsByRequest draait hem om.
 *
 *  EERLIJKHEID: staat er geen beslissende overeenkomst in de graaf, dan blijft
 *  deze regel weg. Er wordt geen "afgewezen"- of "in behandeling"-status
 *  verzonnen: die kent het profiel niet, en de afwezigheid van een beslissing
 *  in de geladen bronnen zegt er niets over. */
export function BeslistIn(props: { iri?: string | null }): JSX.Element {
  const items = () => {
    const m = model() as any;
    if (!m || !props.iri) return [];
    return (agreementsByRequest(m).get(props.iri) || []) as Verwijzing[];
  };
  const delen = () => tekst('decidedIn.line', { agreement: SLEUF }).split(SLEUF);
  return (
    <Show when={items().length}>
      <span class="answered-by-line">
        <For each={items()}>{(a, i) => (
          <>
            {i() ? '; ' : ''}
            <span class="answered-by" title={tekst('decidedIn.title')}>
              <span>{delen()[0]}</span>
              {/* BEVINDING I-3: een SPRONG naar de Overeenkomsten-sectie, geen
                  herlading naar `?policy=` (jumpLink, doc.js r.3840). */}
              <KaartSprong iri={a.iri} titel={tekst('jump.toAgreement')}>
                <span>{a.title || a.curie || a.iri}</span>
              </KaartSprong>
              <Show when={delen()[1]}>{(na) => <span>{na()}</span>}</Show>
            </span>
          </>
        )}</For>
      </span>
    </Show>
  );
}

/** Compacte versie-/herkomstregel als platte tekst (versionLine). Pure functie,
 *  zodat de pariteit met de oude regel los toetsbaar is. */
export function versieRegel(v?: Versie | null): string | null {
  if (!v) return null;
  const delen: string[] = [];
  if (v.effectiveFrom) delen.push(tekst('vline.validFrom', { date: v.effectiveFrom }));
  if (v.effectiveTo) delen.push(tekst('vline.validTo', { date: v.effectiveTo }));
  if (v.revisionOf) {
    delen.push(tekst('vline.replaces', { refs: v.revisionOf.label || v.revisionOf.curie }));
  }
  if (v.supersededBy && v.supersededBy.length) {
    // Puntkomma tussen items: wet- en besluittitels bevatten zelf komma's.
    delen.push(tekst('vline.supersededBy', {
      refs: v.supersededBy.map((s) => s.label || s.curie).join('; '),
    }));
  }
  if (v.derivedFrom && v.derivedFrom.length) {
    delen.push(tekst('vline.derivedFrom', {
      refs: v.derivedFrom.map((d) => d.label || d.curie).join('; '),
    }));
  }
  return delen.length ? delen.join(' · ') : null;
}

/** De compacte kopregel van een verzoek: kenmerk · datum · indiener. Op een
 *  verzoek zijn dit de identificerende gegevens, geen drie velden tussen tien
 *  andere — vandaar de subtitel in plaats van de definitielijst. */
function VerzoekSubtitel(props: { pol: Policy }): JSX.Element {
  const stukken = (): JSX.Element[] => {
    const uit: JSX.Element[] = [];
    const p = props.pol;
    if (p.identifier) uit.push(<span class="mono muted doc-ref">{p.identifier}</span>);
    const d = dayDate(p.issued);
    if (d) uit.push(<span class="muted">{d}</span>);
    const wie = policyAssignee(p) as Partij | null;
    const naam = wie && (wie.label || wie.curie || wie.iri);
    if (naam) uit.push(<span>{naam}</span>);
    return uit;
  };
  return (
    <Show when={stukken().length}>
      <p class="req-sub">
        <For each={stukken()}>{(s, i) => <>{i() ? ' · ' : ''}{s}</>}</For>
      </p>
    </Show>
  );
}

/** De dataset waar dit aanbod aan hangt (dcat:hasPolicy). */
function datasetVan(pol: Policy): any {
  const m = model() as any;
  if (!m) return null;
  return m.datasets.find((d: any) => d.iri === pol.datasetIri
    || (d.policies || []).includes(pol.iri)) || null;
}

function profielWaarde(pol: Policy): JSX.Element | null {
  return pol.profile ? <span class="mono muted">{curie(pol.profile)}</span> : null;
}

function kenmerkWaarde(pol: Policy): JSX.Element | null {
  return pol.identifier ? <span class="mono muted doc-ref">{pol.identifier}</span> : null;
}

// --- OVERIGE EIGENSCHAPPEN --------------------------------------------------
// Alles wat het model wél leest maar de kaart niet in een eigen veld toont
// (extraProperties): de wettelijke GRONDSLAG (dpv:hasLegalBasis), de BRON
// (dct:source), redactionele notities, profielspecifieke predicaten. Ze staan
// als gewone label+waarde-rijen onder de definitielijst — de naam van de
// eigenschap komt uit de graaf, niet uit een lijstje in de code, zodat een
// onbekend predicaat leesbaar blijft in plaats van te verdwijnen.
//
// GRONDSLAG BOVEN BRON: twee dingen die op elkaar lijken maar het niet zijn —
// waaróp de regel rust versus uit welk stuk de verklaring komt. Beide worden
// uit de rij gelicht en op de vroegste van hun twee posities teruggezet, zodat
// de rest van de volgorde (die van de bron) onaangeroerd blijft.
const GRONDSLAG_IRI = 'https://w3id.org/dpv#hasLegalBasis';
const BRON_IRI = 'http://purl.org/dc/terms/source';
const GEKOPPELDE_SLEUTEL: Record<string, string> = {
  [GRONDSLAG_IRI]: 'field.legalBasis', [BRON_IRI]: 'field.origin',
};

export interface ExtraEigenschap {
  predicate: { iri: string; curie: string; label: string };
  values: { literal?: string; blank?: boolean; iri?: string; curie?: string; label?: string }[];
}

export function grondslagEerst(lijst: ExtraEigenschap[]): ExtraEigenschap[] {
  const gr = lijst.filter((ep) => ep.predicate.iri === GRONDSLAG_IRI);
  const br = lijst.filter((ep) => ep.predicate.iri === BRON_IRI);
  if (!gr.length || !br.length) return lijst;
  const rest = lijst.filter((ep) => !gr.includes(ep) && !br.includes(ep));
  const op = Math.min(lijst.indexOf(gr[0]), lijst.indexOf(br[0]));
  const voor = lijst.slice(0, op).filter((ep) => rest.includes(ep));
  return [...voor, ...gr, ...br, ...rest.slice(voor.length)];
}

/** Eén waarde van een overige-eigenschaprij, zoals zij er altijd al uitzag. */
function ExtraWaardeTekst(props: {
  v: ExtraEigenschap['values'][number]; bron: boolean;
}): JSX.Element {
  return (
    <Show
      when={props.v.literal === undefined}
      fallback={<LangeTekst tekst={props.v.literal} />}
    >
      <Show when={!props.v.blank} fallback={<span class="blank-summary">{props.v.label}</span>}>
        <Show
          when={props.bron && /^https?:/.test(props.v.iri || '')}
          fallback={(
            <span title={props.v.iri}>
              {props.v.label}{' '}<span class="mono muted">{props.v.curie}</span>
            </span>
          )}
        >
          <a href={props.v.iri} target="_blank" rel="noopener">{props.v.label}</a>
        </Show>
      </Show>
    </Show>
  );
}

// DE VERWIJZINGSREGEL DIE EEN KAART WORDT.
//
// Hier landt in een domeinprofiel de hele GLS-laag: `gd:gegevens-
// leveringsspecificatie`, `gd:heeftRol` en `gd:akkoordverklaring` staan
// op de GLP-kaart als "overige eigenschap" — het model leest ze wél, de kaart
// had er geen eigen veld voor. Ze toonden een naam met een curie erachter en
// verder niets, terwijl de graaf van diezelfde knoop een volledig formulier
// draagt.
//
// Deze plek is met opzet gekozen boven de doelwit- en partijvelden: zij is de
// GENERIEKE plek. Elk predicaat dat een profiel meebrengt en dat de kaart niet
// zelf toont komt hier langs, op de kaart én op de regel (`regels.tsx` gebruikt
// dezelfde `extraRijen`), en de affordance verschijnt dus overal waar een
// profiel een formulier heeft opgeschreven — zonder één regel profielkennis in
// deze component. Een doelwit of een partij heeft al haar eigen weergave (de
// collectiekaart, de partij-tag); dáár zou een tweede kaart de eerste
// verdringen.
function extraWaarde(ep: ExtraEigenschap, plekVan: string): JSX.Element {
  // DE AANHECHTPLEK VAN DEZE RIJ (14 sep 2026). Zie `KnoopKeten` in
  // formulier.tsx: de open-sleutel van een knoopvouw is de keten van voorouders,
  // en die keten moet bij de PLEK beginnen — anders delen vijf kaartrijen die
  // naar dezelfde knoop wijzen één administratie en klapt een herlading er vijf
  // subbomen open waar de lezer er één opende. Knoop plus predicaat: twee rijen
  // op dezelfde kaart zijn twee plekken, en dezelfde rij op twee kaarten ook.
  const plek = `${plekVan}#${ep.predicate.iri}`;
  // Een grondslag of bron scheidt met ';' — wettitels bevatten zelf komma's —
  // en een externe http(s)-waarde is daar een échte link.
  const bron = !!GEKOPPELDE_SLEUTEL[ep.predicate.iri];
  // Poort op de RIJ en niet op de losse waarde: is er niets gedekt, dan blijft
  // de rij letterlijk de kommatekst die zij altijd was — dat is het geval van
  // elk corpus zonder profiel-formulieren, en daar hoort geen pixel te wijzigen.
  const gedekt = () => ep.values.some((v) => v.iri && dektKnoop(v.iri));
  return (
    <Show when={!gedekt()} fallback={(
      <div class="knoop-vouwen">
        <KnoopKeten.Provider value={[plek]}>
          <For each={ep.values}>{(v) => (
            <KnoopVouw iri={v.iri}><ExtraWaardeTekst v={v} bron={bron} /></KnoopVouw>
          )}</For>
        </KnoopKeten.Provider>
      </div>
    )}
    >
      <span>
        <For each={ep.values}>{(v, i) => (
          <>
            {i() ? (bron ? '; ' : ', ') : ''}
            <ExtraWaardeTekst v={v} bron={bron} />
          </>
        )}</For>
      </span>
    </Show>
  );
}

/** DE ✎-STAND VAN EEN OVERIGE-EIGENSCHAPRIJ — waaronder de BRON (dct:source) en
 *  de wettelijke grondslag. Drie redenen om zo'n rij niet als één veld te
 *  bewerken, elk met hun eigen zin; ze komen letterlijk uit de fase C-grens van
 *  `formRowVeld` (doc.js r.8985-9000):
 *
 *   - MEER DAN ÉÉN WAARDE: `InlineVeld` en `IriCombobox` zijn enkelwaardige
 *     widgets, en `zetLiteral`/`setIri` zouden de andere waarden meenemen;
 *   - een SAMENGESTELDE (blank) waarde: die is niet als één tekst of één IRI
 *     terug te schrijven;
 *   - geen waarde om aan te wijzen.
 *
 *  In alle drie de gevallen blijft het ✎ staan, gedimd, met de reden erin. */
function extraSpec(ep: ExtraEigenschap, term: unknown): {
  soort: 'tekst' | 'iri'; nvt?: string; waarde?: string | null; iri?: string | null;
} {
  const v = ep.values[0];
  if (ep.values.length > 1) {
    return { soort: 'tekst', nvt: tekst('edit.veldMeerwaardig'), waarde: null };
  }
  if (!v) return { soort: 'tekst', nvt: tekst('edit.veldAlLeeg'), waarde: null };
  if (v.blank) return { soort: 'tekst', nvt: tekst('edit.veldBlank'), waarde: null };
  if (v.literal !== undefined) return { soort: 'tekst', waarde: v.literal };
  return { soort: 'iri', iri: v.iri ?? null };
}

/** De rijen van de overige eigenschappen, klaar voor Kv. `term` is de knoop
 *  waarop deze eigenschappen staan; zonder hem blijft de rij leesvorm (de
 *  verkenner en het invulling-paneel gebruiken deze functie ook). */
export function extraRijen(
  lijst?: ExtraEigenschap[] | null, term?: unknown, plek?: string,
): KvRij[] {
  return grondslagEerst(lijst || []).map((ep) => {
    const sleutel = GEKOPPELDE_SLEUTEL[ep.predicate.iri];
    const lees = extraWaarde(ep, plek ?? String(term ?? ''));
    const spec = extraSpec(ep, term);
    return {
      sleutel,
      // De naam van een onbekende eigenschap komt uit de graaf (labelFor op het
      // predicaat), niet uit de stringtabel.
      label: sleutel ? undefined : ep.predicate.label,
      waarde: term === undefined ? lees : (
        <Veld spec={{
          term,
          soort: spec.soort,
          preds: [ep.predicate.iri],
          waarde: spec.waarde,
          iri: spec.iri,
          categorie: 'labeled',
          nvt: spec.nvt,
          label: sleutel ? tekst(sleutel) : ep.predicate.label,
        }}
        >{lees}</Veld>
      ),
    } as KvRij;
  });
}

// --- DE ✎-ROUTES VAN DE BODY (deeltraject 3, golf B) ------------------------
// Vier veldsoorten, vier helpers. Ze zetten alleen een `VeldSpec` om de
// leesnode heen; welke stand dat veld krijgt (bewerkbaar, gelockt, uit) beslist
// de bewerklaag, en in de leesstand rendert `Veld` letterlijk zijn kind — de
// weergave van deeltraject 2 blijft ongemoeid.
//
// ALLEEN GEVULDE RIJEN. `Kv` laat een lege rij weg, en dat blijft zo: een leeg
// veld ZICHTBAAR maken om er iets in te kunnen zetten is de "+"-vorm, en die
// hoort bij de ghost-affordances (lane-ghost-integratie), niet bij deze rijen.
// Het add-geval in de bewerklaag blijft wél bestaan — hij is er voor de specs
// die dáár vandaan komen.

/** De knoop waarop de velden van een kaart landen. Een ANONIEME policy heeft
 *  geen IRI maar wel een term uit de graaf; die is het adres. */
function knoopVan(pol: Policy): unknown {
  return pol.anon ? (pol as { term?: unknown }).term : pol.iri;
}

/** Een TEKSTVELD (kenmerk, en alles wat als losse literal in een rij staat). */
function tekstVeld(pol: Policy, preds: readonly string[], waarde: string | null | undefined,
  lees: JSX.Element): JSX.Element {
  return <Veld spec={{ term: knoopVan(pol), soort: 'tekst', preds, waarde }}>{lees}</Veld>;
}

/** Een DATUMVELD: een `<input type=date>` in de bewerkstand, en xsd:date als
 *  vorm zodra het veld nieuw is — anders valt de datum uit de sortering. */
function datumVeld(pol: Policy, preds: readonly string[], waarde: string | null | undefined,
  lees: JSX.Element): JSX.Element {
  return <Veld spec={{ term: knoopVan(pol), soort: 'datum', preds, waarde }}>{lees}</Veld>;
}

/** Een PARTIJVELD: een IRI-combobox over de partijen uit de graaf. Bewust
 *  `parties` en niet `labeled`: een aanbieder kiezen uit alles met een label is
 *  geen keuze maar een lijst. Vrij intypen blijft kunnen (elke IRI is geldig in
 *  RDF); de suggesties zijn een hulpmiddel, geen keurslijf. */
function partijVeld(pol: Policy, preds: readonly string[], partij: Partij | null | undefined,
  lees: JSX.Element, nvt?: string, hint?: string): JSX.Element {
  return (
    <Veld spec={{
      term: knoopVan(pol), soort: 'iri', preds, iri: partij?.iri ?? null,
      // `nieuweGroep`: naast een IRI mag hier ook een odrl:PartyCollection
      // ontstaan — zie `VeldSpec.nieuweGroep`. Elk partijveld draagt hem, want
      // de vraag "kan deze partij een groep zijn" heeft op een aanbieder
      // hetzelfde antwoord als op een afnemer.
      categorie: 'parties', nvt, hint, nieuweGroep: true,
    }}
    >{lees}</Veld>
  );
}

/** EEN MOET-PARTIJRIJ (aanbieder, afnemer): in de kijkstand alleen als zij een
 *  waarde heeft, in de BEWERKSTAND ook zonder.
 *
 *  ZIJ STAAT SINDS 9 SEP 2026 OP ÉLKE PLEK WAAR EEN PARTIJ MAG WONEN, en niet
 *  meer alleen op de Aanbieder-rij van een aanbod en de Afnemer-rij van een
 *  overeenkomst. Eigenaarsbevinding, letterlijk: "Als een set/rule geen afnemer
 *  heeft kan je die niet toevoegen." Dat klopte: de twee andere kaartsoorten
 *  bouwden hun partijrijen met de kale `partijVeld` erin, en die verschijnt
 *  alleen als er al iets staat — dus was er op een Set, een verzoek en een
 *  overeenkomst-zonder-aanbieder geen plek waar de eerste kon ontstaan. De
 *  REGEL-kant staat in `ui/kaart/regels.tsx`, om dezelfde reden en met dezelfde
 *  vorm.
 *
 *  Dat tweede is de eigenaarsbevinding van 9 sep 2026 ("Placeholders als (vul
 *  aanbieder in) … zijn echt tekst in het invoerveld i.p.v. subtle hints die
 *  verdwijnen als je begint te typen"). Het skelet vulde deze twee relaties met
 *  een geminte partij en een label "(vul aanbieder in)"; dat verzinsel is uit
 *  `createSkeleton`/`addAgreement` weg, en daarmee zou de rij in de bewerkstand
 *  helemaal verdwijnen — geen plek meer waar de eerste aanbieder kan ontstaan.
 *  Dezelfde uitzondering als de Doelobjecten-rij en de Actie-rij van een regel
 *  (`regels.tsx`), om dezelfde reden.
 *
 *  De lege rij staat er niet KAAL: haar combobox draagt de hint in het
 *  `placeholder`-attribuut, en die verdwijnt zodra de gebruiker typt — het
 *  native gedrag, geen tekst in de data. */
function partijRij(pol: Policy, sleutel: string, preds: readonly string[],
  partij: Partij | null | undefined, hintSleutel: string, nvt?: string): KvRij {
  const toon = partij || bewerklaagActief();
  return {
    sleutel,
    waarde: toon
      ? partijVeld(pol, preds, partij, partij ? <Ref agent={partij} /> : <></>,
        nvt, tekst(hintSleutel))
      : null,
    ref: partij?.iri,
  };
}

// --- De rijenlijst per kaartsoort -------------------------------------------
// AFSPRAAK MET Kv: een rij zonder waarde geeft `null`, nooit een component die
// niets rendert. Kv kan een leeg JSX-element niet van een gevuld onderscheiden
// (het is in Solid allebei een object), en zou dan een lege dt/dd-rij tekenen.

/** Een lijstwaarde, of null als de lijst leeg is. */
function lijstOfNiets<T>(lijst: T[] | null | undefined,
  maak: (l: T[]) => JSX.Element): JSX.Element | null {
  return lijst && lijst.length ? maak(lijst) : null;
}

function offerRijen(pol: Policy): KvRij[] {
  const ds = datasetVan(pol);
  return [
    partijRij(pol, 'field.assigner', PRED.ASSIGNER, pol.assigner, 'edit.hintAanbieder'),
    {
      // "Dataset" is een eigen woord van de weergave zonder term erachter.
      label: tekst('field.dataset'),
      waarde: ds ? <span>{ds.title}{' '}<span class="mono muted">{ds.curie}</span></span> : null,
      ref: ds ? ds.iri : null,
    },
    { sleutel: 'field.issued', waarde: datumRij(pol) },
    { sleutel: 'field.derivedFrom', waarde: lijstOfNiets(pol.version?.derivedFrom, (l) => <ProvRefs lijst={l} />) },
    { sleutel: 'field.profile', waarde: profielWaarde(pol) },
    { sleutel: 'field.reference', waarde: kenmerkRij(pol) },
  ];
}

/** De datum-rij, met haar ✎. `pol.issued` is de kale tekst uit het model; die
 *  blijft de leesvorm. */
function datumRij(pol: Policy): JSX.Element | null {
  if (!pol.issued) return null;
  return datumVeld(pol, PRED.ISSUED, pol.issued, <>{pol.issued}</>);
}

/** De kenmerk-rij (dct:identifier), met haar ✎. */
function kenmerkRij(pol: Policy): JSX.Element | null {
  const lees = kenmerkWaarde(pol);
  if (!lees) return null;
  return tekstVeld(pol, PRED.IDENTIFIER, pol.identifier, lees);
}

// TWEE BODY'S IN DE OUDE VIEWER, ÉÉN HIER. De overeenkomst had er twee:
// agreementBody (in de lijst) en fillAgreementPage (de ?policy=-detailpagina).
// De detailpagina toont drie velden méér — Aanbieder, "Vult aanbod in" en
// Profiel — die in de lijst wegvallen omdat het aanbod daar toch al de sectie
// erboven ís. Eén component, één rijenlijst, met `detail` als schakelaar:
// zonder hem staat er letterlijk wat de lijst toonde.
function agreementRijen(pol: Policy, detail: boolean): KvRij[] {
  // Aanbod, verzoek en bron-document zijn drie soorten wasDerivedFrom-doelwit,
  // elk met hun eigen regel: alleen wat overblijft is "Afgeleid van".
  const verzoekIris = new Set((pol.requests || []).map((r) => r.iri));
  const m = model() as any;
  const afgeleid = (pol.version?.derivedFrom || []).filter((d) => !(pol.offers || []).includes(d.iri)
    && !verzoekIris.has(d.iri)
    && !(m && m.offers.some((o: Policy) => o.iri === d.iri)));
  return [
    partijRij(pol, 'field.assignee', PRED.ASSIGNEE, pol.assignee, 'edit.hintAfnemer'),
    // DE AANBIEDER-RIJ, en waarom haar poort in de bewerkstand ANDERS is.
    //
    // In de KIJKSTAND blijft `detail` de poort: de lijstvorm laat aanbieder,
    // "Vult aanbod in" en profiel weg omdat het aanbod daar de sectie erboven
    // ÍS (agreementBody versus fillAgreementPage). Dat is de pariteit met de
    // bevroren viewer en die verandert niet.
    //
    // In de BEWERKSTAND zou diezelfde poort de aanbieder onbereikbaar maken:
    // een overeenkomst staat in de lijst, en wie hem daar bewerkt kwam nooit
    // langs de detailpagina. `addAgreement` NEEMT de aanbieder over van het
    // aanbod, maar alleen als het aanbod er een draagt — sinds de
    // hintvelden-ronde mint niets er meer een, dus een verse overeenkomst op
    // een verse aanbieder-loze aanbieding heeft er geen. Dan is er zonder deze
    // rij geen enkele plek waar de eerste ontstaat. Dezelfde afweging als bij
    // `actieRij` en de lege Voorwaarden-sectie: de kijkstand houdt de bevroren
    // vorm, de bewerkstand toont wat je moet kunnen aanraken.
    detail || bewerklaagActief()
      ? partijRij(pol, 'field.assigner', PRED.ASSIGNER, pol.assigner, 'edit.hintAanbieder')
      : { sleutel: 'field.assigner', waarde: null, ref: pol.assigner?.iri },
    { sleutel: 'field.issued', waarde: datumRij(pol) },
    {
      sleutel: 'field.replaces',
      waarde: pol.version?.revisionOf ? <ProvRef d={pol.version.revisionOf} /> : null,
      ref: pol.version?.revisionOf?.iri,
    },
    { sleutel: 'field.derivedFrom', waarde: lijstOfNiets(afgeleid, (l) => <ProvRefs lijst={l} />) },
    {
      sleutel: 'field.fulfilsOffer',
      waarde: detail ? lijstOfNiets(pol.offers, (l) => <AanbodLinks iris={l} />) : null,
    },
    { sleutel: 'field.request', waarde: lijstOfNiets(pol.requests, (l) => <VerzoekRegel lijst={l} />) },
    { sleutel: 'field.profile', waarde: detail ? profielWaarde(pol) : null },
    { sleutel: 'field.reference', waarde: kenmerkRij(pol) },
  ];
}

function setRijen(pol: Policy, compact: boolean): KvRij[] {
  // Het aanbod dat een verzoek AANVRAAGT heeft zijn eigen zin ("vraagt … aan")
  // en valt daarmee uit "Afgeleid van".
  const gevraagd = new Set((pol.asksFor || []).map((a) => a.iri));
  const afnemer = policyAssignee(pol) as Partij | null;
  const afgeleid = (pol.version?.derivedFrom || []).filter((d) => !gevraagd.has(d.iri));
  return [
    // DE AANBIEDER VAN EEN SET/VERZOEK — sinds 9 sep 2026 met dezelfde lege rij
    // als op een aanbod. Zie `partijRij`: hier stond de kale `partijVeld`, en
    // die verschijnt alleen als er al iets staat.
    partijRij(pol, 'field.assigner', PRED.ASSIGNER, pol.assigner, 'edit.hintAanbieder'),
    // Compact (de verzoek-vorm): kenmerk, datum en indiener staan al in de
    // subtitel en worden niet nog een keer als definitierij herhaald.
    //
    // De EFFECTIEVE afnemer: die van de policy, of anders die van de eerste
    // regel (BRP-patroon: odrl:assignee staat op de Permission). Zonder die
    // terugval blijft het veld leeg terwijl de afnemer wél in de bron staat.
    //
    // EN PRECIES DAAROM DRAAGT DEZE RIJ NIET ALTIJD EEN ✎ (dt3). Komt de
    // afnemer van de REGEL, dan staat `odrl:assignee` daar en niet op de kaart;
    // hier bewerken zou een tweede afnemer op de policy zetten naast die op de
    // permission — twee waarheden waar er één hoort te staan. Het potlood
    // verdwijnt dan niet, het gaat uit met `edit.afnemerVanRegel` als reden.
    //
    // DE COMPACTE VORM HOUDT HAAR SUBTITEL, MAAR NIET HAAR STILTE. In de
    // KIJKSTAND blijft de rij daar weg (de indiener staat al in `req-sub`); in
    // de bewerkstand staat zij er, want een verzoek zonder afnemer had anders
    // geen enkele plek om er een te krijgen — een subtitel is geen veld.
    compact && !bewerklaagActief()
      ? { sleutel: 'field.assignee', waarde: null, ref: afnemer?.iri }
      : partijRij(pol, 'field.assignee', PRED.ASSIGNEE, afnemer, 'edit.hintAfnemer',
        !afnemer || afnemer === pol.assignee ? undefined : tekst('edit.afnemerVanRegel')),
    { sleutel: 'field.issued', waarde: compact ? null : datumRij(pol) },
    {
      sleutel: 'field.replaces',
      waarde: pol.version?.revisionOf ? <ProvRef d={pol.version.revisionOf} /> : null,
      ref: pol.version?.revisionOf?.iri,
    },
    { sleutel: 'field.derivedFrom', waarde: lijstOfNiets(afgeleid, (l) => <ProvRefs lijst={l} />) },
    { sleutel: 'field.profile', waarde: profielWaarde(pol) },
    { sleutel: 'field.reference', waarde: compact ? null : kenmerkRij(pol) },
  ];
}

/** De toegangspunten van de dataset achter een aanbod (dcat:accessURL). */
function Toegangspunten(props: { pol: Policy }): JSX.Element {
  const urls = () => {
    const ds = datasetVan(props.pol);
    return ds ? (ds.distributions || []).filter((d: any) => d.accessURL) : [];
  };
  return (
    <Show when={urls().length}>
      <div class="servers">
        <TermKop tag="div" sleutel="head.accessPoints" class="servers-label" />
        <For each={urls()}>{(d: any) => (
          <div class="server-row">
            {/* EEN TOEGANGSPUNT IS EEN ADRES UIT DE BRON, en een IRI mag elk
                schema dragen: `<javascript:…>` is geldige Turtle. Zonder deze
                poort stond hier een gewone link die bij een klik script draaide
                in de origin van de app (gemeten op het vergiftigde corpus).
                Onbruikbaar adres = geen link, wél zichtbaar: de lezer hoort te
                zien wat er in zijn bron staat. */}
            <Show
              when={veiligeHref(d.accessURL)}
              fallback={<span class="mono">{d.accessURL}</span>}
            >
              {(h) => <a class="mono" href={h()} target="_blank" rel="noopener">{d.accessURL}</a>}
            </Show>
            <span class="muted">{' — ' + d.label}</span>
          </div>
        )}</For>
      </div>
    </Show>
  );
}

export interface KaartBodyProps {
  pol: Policy;
  /** De kaartsoort; de kaart rekent hem uit (soortVan) en geeft hem door. */
  soort: Kaartsoort;
  /** De compacte verzoek-vorm. */
  compact?: boolean;
  /** De detailvorm (?policy=): op een overeenkomst drie velden méér, die in de
   *  lijst wegvallen omdat het aanbod daar de sectie erboven ís. */
  detail?: boolean;
}

export function KaartBody(props: KaartBodyProps): JSX.Element {
  const rijen = (): KvRij[] => {
    if (props.soort === 'offer') return offerRijen(props.pol);
    if (props.soort === 'agreement') return agreementRijen(props.pol, !!props.detail);
    return setRijen(props.pol, !!props.compact);
  };
  // De versieregel draagt de geldigheid; "Vervangt" en "Afgeleid van" hebben
  // hun eigen rij en worden er hier uit gehouden (setCardBody doet hetzelfde).
  const versie = () => versieRegel(props.pol.version
    ? { ...props.pol.version, revisionOf: null, derivedFrom: [] } : null);
  return (
    <header class="offer-head">
      {/* Blank-node-policy: geen uid-regel — het parser-id staat niet in de
          bron en mag nooit in de weergave lekken. */}
      <Show when={props.pol.curie}>{(c) => <div class="mono muted uid">{c()}</div>}</Show>
      {/* DE TOELICHTING (fase C `toelichtVeld`): meerregelig, want een
          beschrijving van drie zinnen mag niet bij de eerste regelovergang al
          opslaan — Enter is daar een newline, Ctrl/Cmd+Enter of blur bewaart.
          `dragendPred` kiest tussen dct:description en rdfs:comment. */}
      {/* DE ALINEA STAAT ER IN DE BEWERKSTAND OOK ZONDER BESCHRIJVING
          (eigenaarsbevinding 9 sep 2026, tweede ronde). Tot deze ronde vulde
          `createSkeleton` een instructiezin in als `dct:description`, en zolang
          die er stond hoefde deze `Show` niet naar de lege stand te kijken. Nu
          die zin weg is, zou een kaart zonder beschrijving er ook geen meer
          kunnen KRIJGEN: geen alinea betekent geen ✎ en geen veld. Dezelfde
          uitzondering — en dezelfde reden — als bij `partijRij` en `actieRij`:
          in de KIJKSTAND blijft de alinea weg zolang er niets staat, dus de
          leesweergave verandert er geen pixel van. */}
      <Show when={props.pol.description || bewerklaagActief()}>
        <p class="offer-desc">
          <Veld spec={{
            term: knoopVan(props.pol),
            soort: 'tekst',
            preds: PRED.TOELICHT,
            waarde: props.pol.description ?? '',
            meerregelig: true,
            hint: tekst('edit.hintBeschrijving'),
          }}
          >
            <Show when={props.pol.description}>{(d) => <LangeTekst tekst={d()} />}</Show>
          </Veld>
        </p>
      </Show>
      <Show when={props.compact}><VerzoekSubtitel pol={props.pol} /></Show>
      <Show when={(props.pol.asksFor || []).length}>
        <p class="ask-line"><VraagtAan lijst={props.pol.asksFor} /></p>
      </Show>
      {/* Vaste plek in de BODY: bij een verzoek is de uitkomst het eerste wat
          je wilt kunnen vinden, en in de kopregel zou de regel er soms wel en
          soms niet staan — afhankelijk van wat er toevallig geladen is. */}
      <Show when={props.soort === 'request'}>
        <p class="answer-line"><BeslistIn iri={props.pol.iri} /></p>
      </Show>
      <Kv rijen={rijen()} />
      <Show when={props.soort === 'offer'}><Toegangspunten pol={props.pol} /></Show>
      <Show when={versie()}>{(v) => <p class="version-line muted">{v()}</p>}</Show>
      <Kv rijen={extraRijen(props.pol.extraProps, knoopVan(props.pol))} />
      {/* "Gebruikt door N": de andere kant van elke verwijzing naar deze kaart.
          NA de bijzondere velden ("Vult aanbod in", "beslist in"): die zeggen
          WAT een relatie betekent en blijven; deze regel is de rest. Verwijst
          er niets naar, dan tekent de component zelf niets. */}
      <Show when={props.pol.iri}>{(iri) => <Terugverwijzingen iri={iri()} />}</Show>
    </header>
  );
}
