// HET SECTIEFILTER — alle filters van één lijstsectie achter één trechter.
//
// Gedragsbron: het sectiefilter-blok van de bevroren viewer (viewer-bevroren/assets/
// doc.js, `sectionFilterControl` en `filterToUrl`). De sectiekop draagt rechts
// een trechter-icoon; dat toont een paneel direct onder de kop met alle filters
// van die sectie bijeen:
//   - een ZOEKVELD op titel of afnemer (client-side, niet in de adresbalk);
//   - bij de Overeenkomsten-sectie een AANBOD-keuze (?aanbod=);
//   - een LEVENSFASE-keuze (?status=), tenzij de sectie er geen kent.
// De filters combineren met EN, het paneel staat standaard dicht, het icoon
// kleurt accent zodra er iets aanstaat, en de "x van y"-teller staat ALTIJD op
// de sectiekop — ook als het paneel dicht is en de sectie ingeklapt.
//
// HET GROEPEERPAD hoort er sinds taak 7 bij en staat in `pivot.tsx`: het
// filterpaneel bepaalt WELKE kaarten je ziet, het pad hoe de regels BINNEN die
// kaarten genest zijn. Dat is dezelfde vraag ("wat wil ik zien, en hoe
// geordend?") en het is de enige fold-out op de sectiekop, dus de lezer hoeft er
// geen tweede te leren kennen. Wat hier verder staat is de eerste-beeld-DEMPING:
// filters die op de nog onvolledige index steunen (status en aanbod) gaan uit,
// het zoekveld blijft bedienbaar.
//
// WAAR DE STAND WOONT — één ruling met gevolgen. Het statusfilter en het
// aanbodfilter staan in de WEERGAVESTORE (en dus in de adresbalk), niet per
// sectie apart: ?status= is één parameter, dus één keuze. De bevroren viewer
// gaf elke sectie een eigen kopie die naar diezelfde parameter schreef — twee
// secties konden daar zichtbaar uit de pas lopen met de URL die ze deelden. Het
// ZOEKVELD blijft wél per sectie (het staat niet in de URL, en "Vlierdam" in de
// Beleidssets zegt niets over de Overeenkomsten).
import { createMemo, createSignal, onCleanup, Show } from 'solid-js';
import type { Accessor, JSX } from 'solid-js';
import { lifecyclePluralWord } from '../../model/parse.js';
import { num } from '../../model/i18n.js';
import { lijstFase } from '../../stores/corpus.js';
import { LEVENSCYCLI, tekst, weergave, zetWeergave } from '../../stores/weergave.js';
import type { Levenscyclus } from '../../stores/weergave.js';
import { Groepeerpad, groeperingAfwijkend, herstelGroepering, sluitDimMenu } from './pivot.jsx';
import './lijst.css';

/** Eén aanbod in de aanbod-keuze van de Overeenkomsten-sectie. */
export interface AanbodOptie { iri: string; title: string }

export interface SectiefilterOpties {
  /** Sectie-id; ook de sleutel waaronder de sectie haar filter terugvindt. */
  id: string;
  /** Kent deze sectie levensfasen? Verzoeken niet (geen geldigheidsperiode):
   *  drie loze keuzes in het paneel zijn erger dan geen keuze. */
  metStatus?: boolean;
  /** De aanbod-keuze. Aanwezig = deze sectie beheert ?aanbod=. */
  aanbod?: () => AanbodOptie[];
  /** Toegankelijke naam van het zoekveld. */
  ariaLabel?: string;
}

export interface Sectiefilter {
  id: string;
  metStatus: boolean;
  aanbodOpties: Accessor<AanbodOptie[]>;
  /** De ingetikte zoektekst (per sectie, niet in de adresbalk). */
  tekst: Accessor<string>;
  zetTekst: (v: string) => void;
  /** De gekozen aanbod-IRI ('' = alle). */
  aanbodIri: Accessor<string>;
  zetAanbod: (iri: string) => void;
  /** De hele filterstand als één waarde: leest ALLEEN de keuzes zelf, nooit het
   *  model. De kaartenlijst herstart haar chunks hierop — zie `maakSectiefilter`
   *  voor waarom dat onderscheid draagt. */
  stand: Accessor<string>;
  /** De gekozen levensfasen (null = alle). */
  status: Accessor<Levenscyclus[] | null>;
  zetStatus: (v: Levenscyclus[] | null) => void;
  /** Laat deze levensfase het statusfilter door? */
  past: (status: string | null | undefined) => boolean;
  /** Staat er iets aan? (kleurt de trechter, toont het wis-kruisje) */
  actief: Accessor<boolean>;
  /** "· aanbod: X · alleen actieve" achter de teller. */
  suffix: Accessor<string>;
  /** De teller op de sectiekop: "· 12" of "· 3 van 12 · alleen actieve". */
  tellingTekst: Accessor<string>;
  /** De lijst meldt hier hoeveel er staan en hoeveel er zijn. */
  zetTelling: (zichtbaar: number, totaal: number) => void;
  /** Alles wissen (ook gebruikt door een sprong die een verborgen kaart moet
   *  tonen). */
  wis: () => void;
  open: Accessor<boolean>;
  zetOpen: (v: boolean) => void;
  /** Eerste-beeld-fase van de tweefasige endpoint-lading: de index is nog
   *  onvolledig, dus de filters die daarop steunen liegen. */
  laadt: Accessor<boolean>;
}

/** De filterstand van één sectie. Een gewoon object (geen component), zodat de
 *  sectiekop de trechter en het paneel op twee plekken kan zetten en de lijst
 *  ernaast zijn rijen kan zeven. */
export function maakSectiefilter(opties: SectiefilterOpties): Sectiefilter {
  const [tekstWaarde, zetTekstWaarde] = createSignal('');
  const [open, zetOpen] = createSignal(false);
  const [zichtbaar, zetZichtbaar] = createSignal(0);
  const [totaal, zetTotaal] = createSignal(0);
  const metStatus = opties.metStatus !== false;
  const aanbodOpties = () => (opties.aanbod ? opties.aanbod() : []);
  const metAanbod = () => aanbodOpties().length > 0;

  const status = () => (metStatus ? weergave.filters.status : null);
  // Een ONBEKENDE deeplinkwaarde valt terug op "alle" — precies zoals de
  // bevroren viewer, die de waarde valideert vóór hij hem toepast
  // (`offerSel.value = offerTitle.has(want) ? want : ''`, doc.js r.7283).
  // Zonder die poort toonde een verouderde of vertypte ?aanbod=-link een LEGE
  // sectie in plaats van de hele lijst (dt3-opruimlijst punt 1: 3 kaarten /
  // 1 overeenkomst bevroren tegen 2 / 0 nieuw). De parameter zelf blijft in de
  // adresbalk staan; de viewer herschrijft hem daar ook niet.
  const aanbodIri = () => {
    const want = metAanbod() ? weergave.filters.aanbod : '';
    return aanbodOpties().some((o) => o.iri === want) ? want : '';
  };

  const zetStatus = (v: Levenscyclus[] | null) => {
    zetWeergave({ filters: { ...weergave.filters, status: v } });
  };
  const zetAanbod = (iri: string) => {
    zetWeergave({ filters: { ...weergave.filters, aanbod: iri } });
  };

  // Ook een afwijkende GROEPERING telt als "er staat iets aan": zij verandert
  // het beeld net zo goed, en zonder dit zou een gedeelde ?groupby=-link in een
  // dichtgeklapt paneel onzichtbaar zijn (doc.js: `anyActive || groupByIsCustom`).
  // Bewust hier en NIET in `stand()`: die stuurt de chunk-herstart en mag het
  // model niet lezen — zie de opmerking daar.
  const actief = createMemo(() => !!tekstWaarde() || !!status() || !!aanbodIri()
    || groeperingAfwijkend());

  const suffix = () => {
    let uit = '';
    const off = aanbodIri();
    if (off) {
      const o = aanbodOpties().find((x) => x.iri === off);
      uit += tekst('filter.suffixOffer', { title: (o && o.title) || off });
    }
    const st = status();
    if (!st) return uit;
    if (!st.length) return uit + tekst('filter.suffixNoStatus');
    const woorden = LEVENSCYCLI.filter((s) => st.includes(s))
      .map((s) => lifecyclePluralWord(s) as string);
    return uit + ' · ' + (woorden.length === 1
      ? tekst('filter.suffixOnly', { word: woorden[0] }) : woorden.join(' + '));
  };

  // DE FILTERSTAND ALS ÉÉN WAARDE — de sleutel waarop de kaartenlijst haar
  // chunks herstart. Bewust NIET samengesteld uit `aanbodIri()`/`status()`: die
  // twee lezen `metAanbod()` → `aanbodOpties()` → de aanbod-memo → `model()`,
  // dus élke modelherbouw liet ze opnieuw melden en herstartte de lijst in élke
  // sectie — ook in Verzoeken en Beleidssets, die helemaal geen aanbodkeuze
  // hebben. Dat was de wortel van NB-1 (de sprong voorbij de eerste chunk
  // strandde) en I-5 (de lijstpositie sprong terug naar één chunk zodra je een
  // kaart uitklapte).
  //
  // Hier staan alleen de RUWE keuzes: het lokale tekstsignaal en de twee
  // URL-velden, elk pas meegeteld als deze sectie dat filter überhaupt heeft.
  // `opties.aanbod`/`metStatus` zijn statische eigenschappen van de sectie, geen
  // signalen — er loopt dus geen draad meer van het model naar de herstart.
  const stand = createMemo(() => [
    tekstWaarde(),
    opties.aanbod ? weergave.filters.aanbod : '',
    metStatus ? (weergave.filters.status || []).join(',') : '',
  ].join('\u0000'));

  const tellingTekst = () => {
    // Eerste-beeld-fase: het totaal is nog onbekend (de lijst is per soort
    // afgekapt), dus staat er "…" in plaats van een getal dat zou liegen.
    if (lijstFase() === 'eerste') return '· …';
    const n = zichtbaar();
    const t = totaal();
    return '· ' + (n === t ? num(t) : tekst('count.ofTotal', { n, total: t })) + suffix();
  };

  return {
    id: opties.id,
    metStatus,
    aanbodOpties,
    tekst: tekstWaarde,
    zetTekst: zetTekstWaarde,
    aanbodIri,
    zetAanbod,
    stand,
    status,
    zetStatus,
    past: (s) => {
      const st = status();
      return !st || st.includes((s || 'active') as Levenscyclus);
    },
    actief,
    suffix,
    tellingTekst,
    zetTelling: (n, t) => { zetZichtbaar(n); zetTotaal(t); },
    wis: () => {
      zetTekstWaarde('');
      // Het wis-kruisje wist ook de GROEPERING: terug naar de bronvolgorde.
      herstelGroepering();
      zetWeergave({ filters: { status: null, aanbod: metAanbod() ? '' : weergave.filters.aanbod } });
    },
    open,
    zetOpen,
    laadt: () => lijstFase() === 'eerste',
  };
}

/** De trechter op de sectiekop. Hij zit in een <summary>: klikken mag de SECTIE
 *  niet in-/uitklappen — vandaar preventDefault én stopPropagation. */
export function Filterknop(props: { filter: Sectiefilter }): JSX.Element {
  const f = () => props.filter;
  return (
    <button
      type="button"
      class={'sec-filter-btn' + (f().actief() ? ' on' : '')}
      aria-expanded={f().open()}
      aria-haspopup="true"
      title={f().laadt() ? tekst('filter.loading') : tekst('filter.title')}
      aria-label={tekst('filter.toggleAria')}
      onClick={(e) => { e.preventDefault(); e.stopPropagation(); f().zetOpen(!f().open()); }}
      onPointerDown={(e) => e.stopPropagation()}
    >
      {/* Trechter als kleine inline-SVG (currentColor, dus themavariabelen
          volgen) — letterlijk die van de bevroren viewer. */}
      <svg viewBox="0 0 16 16" width="13" height="13" aria-hidden="true">
        <path d="M1.5 2.5h13L9.5 8.6v4.3l-3 1.6V8.6z" fill="currentColor" />
      </svg>
    </button>
  );
}

/** Eén filterregel in het paneel: label + bedieningselement. */
function Item(props: { label: string; children: JSX.Element }): JSX.Element {
  return (
    <div class="sec-filter-item">
      <span class="sec-filter-lab">{props.label}</span>
      {props.children}
    </div>
  );
}

/** De statuskeuze. Eén select met "(alle)" plus de drie enkelvoudige fasen; een
 *  COMBINATIE uit de adresbalk (?status=active,terminated) blijft als extra
 *  optie staan, zodat een gedeelde link nooit stil verbouwd wordt. */
function Statuskeuze(props: { filter: Sectiefilter }): JSX.Element {
  const f = () => props.filter;
  const waarde = () => {
    const st = f().status();
    return st ? LEVENSCYCLI.filter((s) => st.includes(s)).join(',') : '';
  };
  const combinatie = () => {
    const w = waarde();
    return w && !(LEVENSCYCLI as string[]).includes(w) ? w : '';
  };
  return (
    <select
      class="sec-filter-status"
      aria-label={tekst('filter.status')}
      disabled={f().laadt()}
      title={f().laadt() ? tekst('filter.loading') : undefined}
      value={waarde()}
      onChange={(e) => {
        const v = e.currentTarget.value;
        f().zetStatus(v ? (v.split(',') as Levenscyclus[]) : null);
      }}
    >
      <option value="">{tekst('filter.all')}</option>
      {LEVENSCYCLI.map((s) => (
        <option value={s}>{lifecyclePluralWord(s) as string}</option>
      ))}
      <Show when={combinatie()}>{(w) => (
        <option value={w()}>
          {w().split(',').map((s) => lifecyclePluralWord(s) as string).join(' + ')}
        </option>
      )}</Show>
    </select>
  );
}

/** Het filterpaneel onder de sectiekop. Escape sluit het; een klik ERBUITEN
 *  niet — het paneel is een inline blok en moet blijven staan terwijl de lezer
 *  in de gefilterde lijst klikt.
 *
 *  GELAAGD: staat het dimensiemenu van het groepeerpad open, dan sluit Escape
 *  ÉÉRST dat — één toetsaanslag hoort één ding af te breken, niet ook nog het
 *  paneel eronder (doc.js r.7408). */
export function Filterpaneel(props: { filter: Sectiefilter }): JSX.Element {
  const f = () => props.filter;

  const opEscape = (e: KeyboardEvent) => {
    if (e.key !== 'Escape') return;
    if (sluitDimMenu()) return;
    f().zetOpen(false);
  };
  document.addEventListener('keydown', opEscape);
  onCleanup(() => document.removeEventListener('keydown', opEscape));

  return (
    <div
      class={'sec-filter-panel' + (f().laadt() ? ' is-loading' : '')}
      role="group"
      aria-label={tekst('filter.title')}
      hidden={!f().open()}
    >
      <Item label={tekst('filter.search')}>
        <input
          type="search"
          class="set-index-filter"
          placeholder={tekst('filter.placeholder')}
          aria-label={props.filter.id === 'sectie-verzoeken'
            ? tekst('filter.ariaRequests') : tekst('filter.aria')}
          value={f().tekst()}
          onInput={(e) => f().zetTekst(e.currentTarget.value)}
        />
      </Item>
      <Show when={f().aanbodOpties().length}>
        <Item label={tekst('filter.offer')}>
          <select
            class="sec-filter-offer"
            aria-label={tekst('filter.offerAria')}
            disabled={f().laadt()}
            title={f().laadt() ? tekst('filter.loading') : undefined}
            value={f().aanbodIri()}
            onChange={(e) => f().zetAanbod(e.currentTarget.value)}
          >
            <option value="">{tekst('filter.all')}</option>
            {f().aanbodOpties().map((o) => <option value={o.iri}>{o.title}</option>)}
          </select>
        </Item>
      </Show>
      <Show when={f().metStatus}>
        <Item label={tekst('filter.status')}><Statuskeuze filter={props.filter} /></Item>
      </Show>
      {/* Onderaan het paneel, na de zeef en vóór het wis-kruisje: eerst WELKE
          kaarten, dan HOE de regels erbinnen genest zijn. */}
      <Groepeerpad />
      {/* "Wis filters" als kruisje rechtsboven: vaste plek, geen regelruimte,
          en zichtbaar zodra er iets te wissen valt. */}
      <button
        type="button"
        class="sec-filter-clear"
        title={tekst('filter.clear')}
        aria-label={tekst('filter.clear')}
        disabled={f().laadt()}
        hidden={!f().actief()}
        onClick={() => f().wis()}
      >
        ×
      </button>
    </div>
  );
}
