// DE GROEPERING (pivot): welke dimensies de regels ordenen, en in welke
// volgorde.
//
// Gedragsbron: het pivot-blok van de bevroren viewer (viewer-bevroren/assets/doc.js —
// `groupByFromUrl`, `declaredDimensions`, `activeDimensions`, `groupByToUrl`,
// `applyGroupBy`, `pivotChip`, `pivotAddChip`, `pivotItem`).
//
// De BRON declareert welke refinement-dimensies de regels ordenen en in welke
// volgorde ze nesten (qb:DimensionProperty + sh:order, zie parse.js). De LEZER
// bepaalt wat hij daarvan aanzet: elke dimensie kan uit (dan verdwijnt dat
// niveau) en de volgorde waarin hij ze aanzet is de nestvolgorde — "per doel de
// doelgroepen" of "per doelgroep de doelen", of gewoon een platte lijst.
// Dezelfde regels, andere as.
//
// DRIE STANDEN, en het verschil tussen de eerste twee is precies wat de lezer
// bedoelde (`?groupby=`, buitenste eerst):
//   - parameter AFWEZIG          -> de gedeclareerde volgorde (alles aan);
//   - parameter LEEG (?groupby=) -> alles uit: platte lijst;
//   - parameter met namen        -> die dimensies, in die nestvolgorde.
// De parameter is ADVIES, geen bevel: onbekende namen worden genegeerd
// (`pivotDimensions`). Een verouderde link maakt de lijst hooguit platter,
// nooit stuk.
//
// WAAR DE KEUZE WOONT — anders dan in de bevroren viewer, en met opzet. Daar
// leefde zij in `state.groupBy` en werd de URL alleen beschreven; hier is de
// weergavestore de enige waarheid en volgt de adresbalk haar (`zetWeergave`).
// Dat is hetzelfde deelbaarheids-contract met één bron van waarheid minder, en
// het is wat de keuze een taalwissel of een modelherbouw laat overleven: die
// bouwen de DOM opnieuw op, de store blijft staan.
//
// EN ÉÉN DING VERANDERT NIET: waar de bevroren viewer na elke wissel
// `captureListUi`/`restoreListUi` om een volledige hertekening heen moest
// zetten, doet Solid dat werk met fijnmazige reactiviteit — de open kaarten en
// de filterstand staan in signalen, niet in de DOM, en overleven de hergroep
// vanzelf.
import { createMemo, createSignal, For, Show } from 'solid-js';
import type { JSX } from 'solid-js';
import { groupRules, pivotDimensions } from '../../model/parse.js';
import { model } from '../../stores/corpus.js';
import { tekst, weergave, zetWeergave } from '../../stores/weergave.js';
import type { Regel } from '../kaart/kaart.jsx';
import './lijst.css';

/** Eén gedeclareerde groeperingsdimensie (groupingDimensions in parse.js). */
export interface Dimensie {
  iri: string;
  curie?: string | null;
  label?: string | null;
  order?: number | null;
}

/** Eén knoop uit `groupRules`: een regel, of een niveau met kinderen. */
export type Groepknoop =
  | { kind: 'rule'; rule: Regel; label: string | null }
  | {
    kind: 'group';
    dim: Dimensie;
    value: { iri?: string | null; curie?: string | null; label?: string };
    rules: Regel[];
    children: Groepknoop[];
  };

function declaraties(): Dimensie[] {
  const m = model() as { groupingDimensions?: Dimensie[] } | null;
  return (m && m.groupingDimensions) || [];
}

/** Alle dimensies die de bron declareert, in gedeclareerde volgorde — dat is de
 *  keuzelijst, ongeacht wat er aanstaat. */
export function gedeclareerdeDimensies(): Dimensie[] {
  return pivotDimensions(declaraties(), null) as Dimensie[];
}

/** De dimensies die NU nesten, in nestvolgorde. Leeg = platte lijst. */
export function actieveDimensies(): Dimensie[] {
  return pivotDimensions(declaraties(), weergave.groupBy) as Dimensie[];
}

/** Wijkt de groepering af van wat de bron declareert? Bepaalt of het
 *  wis-kruisje van het filterpaneel verschijnt en of de trechter accent kleurt:
 *  een afwijkende weergave mag niet onzichtbaar zijn in een dichtgeklapt
 *  paneel. */
export function groeperingAfwijkend(): boolean {
  const decl = gedeclareerdeDimensies();
  const act = actieveDimensies();
  return decl.length !== act.length || decl.some((d, i) => d.iri !== act[i].iri);
}

/** De leeskeuze naar de store (en dus de adresbalk). Is zij gelijk aan de
 *  bronvolgorde, dan gaat `groupBy` terug op `null` en verdwijnt de parameter:
 *  de adresbalk draagt alleen wat de lezer ECHT anders wilde. Alles uit schrijft
 *  de parameter LEEG weg — anders zou een gedeelde platte lijst bij de
 *  ontvanger weer gegroepeerd opengaan. */
export function zetGroepering(dims: Dimensie[]): void {
  const decl = gedeclareerdeDimensies();
  const gelijk = decl.length === dims.length && decl.every((d, i) => d.iri === dims[i].iri);
  zetWeergave({ groupBy: gelijk ? null : dims.map((d) => d.curie || d.iri) });
}

/** Eén niveau weghalen (de rest schuift op) — de eerste van de twee
 *  handelingen die het leespad aanbiedt. */
export function haalDimensieWeg(dim: Dimensie): void {
  zetGroepering(actieveDimensies().filter((d) => d.iri !== dim.iri));
}

/** …en er een achteraan hangen, dus als BINNENSTE niveau: de
 *  activeringsvolgorde IS de nestvolgorde. */
export function voegDimensieToe(dim: Dimensie): void {
  const actief = actieveDimensies();
  if (actief.some((d) => d.iri === dim.iri)) return;
  zetGroepering([...actief, dim]);
}

/** Terug naar de bronvolgorde (het wis-kruisje van het filterpaneel wist ook de
 *  groepering). */
export function herstelGroepering(): void {
  zetWeergave({ groupBy: null });
}

// --- Het dimensiemenu: er kan er maar ÉÉN open zijn -------------------------
// Het menu hangt aan de +-chip van een paneel, en een tweede paneel is een
// tweede sectie. Module-breed, zodat Escape en een klik buiten het weten te
// sluiten zonder dat elke chip zijn eigen document-listener aanmaakt.

const [openMenu, zetOpenMenu] = createSignal<symbol | null>(null);
let openDoos: HTMLElement | null = null;

/** Sluit het open dimensiemenu, en zeg of er iets te sluiten viel. Het
 *  filterpaneel gebruikt dat: staat het menu open, dan sluit Escape ÉÉRST dat —
 *  één toetsaanslag hoort één ding af te breken. */
export function sluitDimMenu(): boolean {
  if (openMenu() === null) return false;
  zetOpenMenu(null);
  openDoos = null;
  return true;
}

if (typeof document !== 'undefined' && document.addEventListener) {
  // CAPTURE-fase: de klik die het menu OPENT is op dat moment nog niet
  // geregistreerd (`openMenu` is dan nog leeg), dus die sluit zichzelf niet.
  document.addEventListener('click', (e) => {
    if (openMenu() === null) return;
    const doel = e.target as Node | null;
    if (openDoos && doel && openDoos.contains(doel)) return;
    sluitDimMenu();
  }, true);
}

// --- Het leespad ------------------------------------------------------------

function naam(d: Dimensie): string {
  return d.label || d.curie || d.iri;
}

/** Eén actieve dimensie in het pad: het label plus het × dat hem eruit haalt. */
function Dimchip(props: { dim: Dimensie }): JSX.Element {
  const label = () => naam(props.dim);
  const titel = () => tekst('pivot.remove', { label: label() });
  return (
    <span class="sec-filter-dim">
      <span class="sec-filter-dim-lab">{label()}</span>
      <button
        type="button"
        class="sec-filter-dim-x"
        title={titel()}
        aria-label={titel()}
        onClick={(e) => {
          e.preventDefault();
          sluitDimMenu();
          haalDimensieWeg(props.dim);
        }}
      >
        ×
      </button>
    </span>
  );
}

/** De +-chip. Bij precies één uitgezette dimensie valt er niets te kiezen en
 *  voegt hij hem meteen toe; bij meer opent hij een klein menu met hun labels. */
function Toevoegchip(props: { rest: Dimensie[] }): JSX.Element {
  const teken = Symbol('dimensiemenu');
  const open = () => openMenu() === teken;
  let doos!: HTMLSpanElement;
  return (
    <span class="sec-filter-dim-wrap" ref={doos}>
      <button
        type="button"
        class="sec-filter-dim-add"
        title={tekst('pivot.add')}
        aria-label={tekst('pivot.add')}
        aria-expanded={open()}
        aria-haspopup="menu"
        onClick={(e) => {
          e.preventDefault();
          e.stopPropagation();
          if (props.rest.length === 1) {
            sluitDimMenu();
            voegDimensieToe(props.rest[0]);
            return;
          }
          const was = open();
          sluitDimMenu();
          if (was) return;
          openDoos = doos;
          zetOpenMenu(teken);
        }}
      >
        +
      </button>
      <Show when={props.rest.length > 1}>
        <div class="sec-filter-dim-menu" role="menu" hidden={!open()}>
          <For each={props.rest}>{(d) => (
            <button
              type="button"
              class="sec-filter-dim-opt"
              role="menuitem"
              title={tekst('pivot.addItem', { label: naam(d) })}
              aria-label={tekst('pivot.addItem', { label: naam(d) })}
              onClick={(e) => {
                e.preventDefault();
                sluitDimMenu();
                voegDimensieToe(d);
              }}
            >
              {naam(d)}
            </button>
          )}</For>
        </div>
      </Show>
    </span>
  );
}

/** Het groepeerpad in het filterpaneel: achter "Groepeer" de ACTIEVE dimensies
 *  als chips in nestvolgorde met "›" ertussen — links is buitenste. Daarachter
 *  een +-chip zolang er dimensies uitstaan. Alles weggehaald is een geldige
 *  stand: de platte lijst, en dan staat er alleen nog de +.
 *
 *  Bij NUL gedeclareerde dimensies staat er niets: een gewone ODRL-bron zonder
 *  qb:DimensionProperty ziet het paneel precies zoals het was. */
export function Groepeerpad(): JSX.Element {
  const alle = createMemo(gedeclareerdeDimensies);
  const actief = createMemo(actieveDimensies);
  const rest = createMemo(() => alle().filter((d) => !actief().some((a) => a.iri === d.iri)));
  return (
    <Show when={alle().length}>
      <div class="sec-filter-item">
        <span class="sec-filter-lab">{tekst('pivot.label')}</span>
        <div class="sec-filter-pivot">
          <For each={actief()}>{(d, i) => (
            <>
              <Show when={i()}>
                <span class="sec-filter-sep" aria-hidden="true">›</span>
              </Show>
              <Dimchip dim={d} />
            </>
          )}</For>
          <Show when={rest().length}><Toevoegchip rest={rest()} /></Show>
        </div>
      </div>
    </Show>
  );
}

// --- De groepering zelf -----------------------------------------------------

/** De regels van één blok als (eventueel geneste) knopen. Zonder declaraties in
 *  de bron is `groupRules` de identiteit en verandert er niets: elke regel
 *  blijft de rij die hij was. */
export function groepeer(regels: Regel[]): Groepknoop[] {
  return groupRules(regels, actieveDimensies()) as Groepknoop[];
}
