/** Het predicaat dat de ACTIE van een regel draagt. Als kale string, om dezelfde
 *  reden als de tabel in `ui/bewerk/haken.tsx`: een import naar `model/edit.js`
 *  vanuit deze LEEScomponent zou de hele serialisatielaag de leeschunk in
 *  trekken. */
const ODRL_ACTION = 'http://www.w3.org/ns/odrl/2/action';

/** HET ADRES WAAROP DE OPEN-STAND VAN EEN RIJ WORDT BEWAARD (eigenaarsbesluit
 *  8 sep 2026, eis 1: een toevoeging mag niets anders open of dicht laten
 *  klappen).
 *
 *  Waarom een rij dit nodig heeft en een kaart niet: de kaart draagt haar
 *  open-stand al in een signaal (`kaartenlijst.tsx`), een regelrij is een kale
 *  <details> en droeg hem in de DOM. Dat gaat goed tot `corpus.ts` de kaart na
 *  een mutatie GERICHT herbouwt — dan zijn de regelobjecten nieuw, hertekent
 *  `<For>` de rijen en is de stand weg (gemeten in `toevoegfocus.mjs`).
 *
 *  De sleutel draagt de KAART erbij (`scope`): dezelfde regel kan in meer dan
 *  één kaart staan, en die twee rijen horen los van elkaar open te kunnen. Binnen
 *  één kaart is het adres van de knoop uniek genoeg — een IRI, en bij een blanke
 *  knoop zijn term-id (`_:b12`), dat binnen een sessie stabiel is. Geen van
 *  beide, dan is er niets te bewaren en levert dit een lege sleutel: de rij
 *  gedraagt zich dan precies als voorheen. */
export function rijSleutel(regel: Regel, scope?: string | null): string {
  const t = (regel as { term?: { id?: string; value?: string } | null }).term;
  const id = regel.iri || (t && (t.id || t.value)) || '';
  return id ? `rij:${scope || ''}|${id}` : '';
}

/** De actie van een regel als descriptor. Een verplichting draagt haar actie
 *  als kaal label (readDuty), een toestemming als object (readPermission). */
function actie(regel: Regel): RegelActie | null {
  if (!regel.action) return null;
  return typeof regel.action === 'string' ? { label: regel.action } : regel.action;
}

/** De naam van een regel zonder eigen dct:title: het actie-label, en daarachter
 *  het doelobject als er precies één is ("Verstrekken · Gegevensset 1"). Bij
 *  meer doelobjecten zou die opsomming de kop laten uitwaaieren; ze staan dan
 *  gewoon in het Doelobjecten-veld van de body. */
function actieTitel(regel: Regel): string | null {
  const a = actie(regel);
  if (!a || !a.label) return null;
  const tg = regel.targets || [];
  return tg.length === 1 && tg[0].label ? `${a.label} · ${tg[0].label}` : a.label;
}

const TERUGVAL_SLEUTEL: Record<string, string> = {
  toestemming: 'title.permission', verbod: 'title.prohibition', duty: 'title.duty',
};

/** De naam die een regelrij draagt. Terugval, generiek: de eigen dct:title (op
 *  een verplichting: rdfs:label), dan de VARIANTNAAM die de groepering afleidt,
 *  dan het ACTIE-label, dan het soortwoord.
 *
 *  Een eigen dct:title wint van de afgeleide variantnaam: de auteur formuleerde
 *  die naam voor de lezer ("… zonder diplomatieke kentekens"), de variantnaam is
 *  een machinale samenvatting van refinement-waarden ("… · false"). */
export function regelTitel(regel: Regel, soort: RegelSoort, naam?: string | null): string {
  const eigen = soort === 'duty' ? regel.label : regel.title;
  return eigen || naam || actieTitel(regel)
    || tekst(TERUGVAL_SLEUTEL[soort] || 'title.permission');
}

/** De parameterregel van een verplichting: WAT de maatregel is (de actie, de
 *  geïnformeerde partij). De voorwaarden staan niet in deze zin maar als eigen
 *  sectie (taak 5) — zelfde structuur als bij een toestemming.
 *
 *  `zonderActie` is de BEWERKSTAND (eis 3 van het eigenaarsbesluit 8 sep 2026):
 *  daar draagt de rij "Actie" de actie als eigen, bewerkbaar veld, en dan zou
 *  deze zin hem verdubbelen. In de kijkstand verandert er niets. */
function plichtParameters(regel: Regel, zonderActie = false): string {
  const delen: string[] = [];
  const a = actie(regel);
  if (!zonderActie && a && a.label && a.label !== regel.label) delen.push(a.label);
  if (regel.informedParty) {
    delen.push(tekst('duty.inform', {
      party: regel.informedParty.label || regel.informedParty.curie,
    }));
  }
  return delen.join(' · ');
}

/** DE ACTIE-RIJ, en waarom zij in de bewerkstand ANDERS staat dan in de
 *  kijkstand (eis 3 van het eigenaarsbesluit 8 sep 2026: "een nieuwe
 *  verplichting komt met 'informeren' prefilled en dat veld is niet editable").
 *
 *  Drie dingen komen hier samen:
 *   1. De KIJKSTAND blijft precies zoals hij was: de actie staat er alleen als
 *      hij niet al de TITEL van de rij is (anders zou de rij zijn eigen kop
 *      herhalen), en een verplichting toont hem helemaal niet als rij — die
 *      draagt hem in haar parameterzin.
 *   2. De BEWERKSTAND toont hem ALTIJD, ook als hij de titel is en ook op een
 *      verplichting. Zonder die uitzondering is de actie van een verse regel
 *      onbereikbaar: hij is dan leeg (`addPermission` vult sinds 9 sep 2026 niets
 *      meer in) of hij komt van `addDuty` (odrl:inform) en valt dan samen met de
 *      titel of staat hij in een zin. Prefillen mag, vastzetten niet.
 *   3. Het veld schrijft via `vorm: 'actie'` — niet met een kale `setIri`. De
 *      actie hangt in ODRL 2.2 als `[ rdf:value <actie> ]` aan de
 *      regel, met de doelbinding als refinement aan diezelfde blanke knoop; een
 *      kale `setIri` zou dat knoopje vervangen en de doelbinding laten vallen. */
function actieRij(regel: Regel, a: RegelActie | null, titel: string): KvRij | null {
  const lees = a && a.label ? (
    <span data-iri={a.iri || undefined}>
      {a.label}
    </span>
  ) : null;
  const zichtbaarInLezen = !!lees && a!.label !== titel;
  if (!bewerklaagActief()) {
    return { sleutel: 'field.action', waarde: zichtbaarInLezen ? lees : null, ref: a?.iri };
  }
  const term = (regel as { term?: unknown }).term ?? regel.iri;
  if (!term) return { sleutel: 'field.action', waarde: zichtbaarInLezen ? lees : null, ref: a?.iri };
  return {
    sleutel: 'field.action',
    ref: a?.iri,
    waarde: (
      <Veld spec={{
        term,
        soort: 'iri',
        preds: [ODRL_ACTION],
        iri: a?.iri ?? null,
        // DE HINT VAN EEN LEGE ACTIE (eigenaarsbevinding 9 sep 2026, tweede
        // ronde). Een verse toestemming of een vers verbod heeft geen actie —
        // `addPermission` vult er sinds de eerste ronde niets meer in — en dan
        // stond hier de ALGEMENE hint van de combobox ("IRI of prefix:naam").
        // Die zegt wat de VORM van de invoer is, niet wat er ingevuld hoort te
        // worden; dat laatste is wat de eigenaar bij "nieuwe toestemming en
        // verbod" miste.
        hint: tekst('edit.hintActie'),
        // HET LABEL ERBIJ, want een VERPLICHTING draagt geen actie-IRI in het
        // model: `readDuty` levert haar actie als kale tekst. Zonder deze regel
        // gaat het veld op een verse verplichting leeg open naast een rij die
        // "Informeren" zegt. Zie `beginIri` in `ui/bewerk/kaartveld.tsx`.
        waarde: a?.label ?? null,
        categorie: 'actions',
        vorm: 'actie',
      }}
      >{lees}</Veld>
    ),
  };
}

/** DE AFNEMER-RIJ VAN EEN REGEL, en waarom zij in de bewerkstand ANDERS staat
 *  dan in de kijkstand — precies dezelfde afweging als `actieRij` hierboven,
 *  voor precies dezelfde soort gat.
 *
 *  EIGENAARSBEVINDING 9 SEP 2026, letterlijk: "Als een set/rule geen afnemer
 *  heeft kan je die niet toevoegen."
 *
 *   1. De KIJKSTAND blijft zoals hij was: de afnemer staat er alleen als hij
 *      AFWIJKT van die van de kaart (`ownerAssignee` in permissionRow) — anders
 *      zou elke rij van dezelfde kaart hem herhalen. En hij was daar puur
 *      leesvorm: een `<Ref>`, zonder enige bewerkroute.
 *   2. De BEWERKSTAND toont hem ALTIJD, als veld op de REGEL. Twee gevallen
 *      lopen daarin samen, en allebei waren ze doodlopend:
 *        - de regel draagt GEEN afnemer: dan is dit de enige plek waar de
 *          eerste kan ontstaan (de kaartrij zou hem op de policy zetten, en dat
 *          is een andere triple met een andere betekenis);
 *        - de regel draagt hem WÉL en de kaart leent hem (het BRP-patroon:
 *          `policyAssignee` valt op de eerste regel terug). Dan zwijgt de rij
 *          in de kijkstand, staat de kaartrij gedimd met
 *          `edit.afnemerVanRegel` als reden — en wees dus naar een plek die er
 *          niet was. Nu is dit die plek.
 *   3. De term is de REGEL, nooit de kaart. `odrl:assignee` landt waar de lezer
 *      hem toevoegt; hier bewerken via de kaartknoop zou een tweede afnemer
 *      naast de eerste zetten. Een BLANKE regel draagt zijn term uit de graaf —
 *      dat is een geldig adres, zie `knoopVan` in body-rijen.tsx. */
function afnemerRij(regel: Regel, eigenAfnemer: Partij | null): KvRij {
  const term = (regel as { term?: unknown }).term ?? regel.iri;
  if (!bewerklaagActief() || !term) {
    return {
      sleutel: 'field.assignee',
      waarde: eigenAfnemer ? <Ref agent={eigenAfnemer} /> : null,
      ref: eigenAfnemer?.iri,
    };
  }
  // DE LEESNODE VAN DE BEWERKSTAND IS DE EIGEN AFNEMER VAN DE REGEL, ZONDER DE
  // "wijkt hij af van de kaart"-toets (randvondst van het re-check, punt 3).
  //
  // Die toets is een KIJKSTAND-regel: zij houdt de afnemer van dezelfde kaart
  // van elke rij af (`ownerAssignee` in permissionRow). In de bewerkstand doet
  // zij iets anders — daar staat het veld er tóch al, en dan onderdrukt zij niet
  // een herhaling maar de WAARDE die je aan het bewerken bent.
  //
  // Gemeten geval: "+ groep" op een regel waarvan de assignee tegelijk de
  // BRP-TERUGVAL van de kaart is (de kaart draagt zelf geen odrl:assignee, dus
  // `policyAssignee` leent die van deze regel). De mint en de koppeling gingen
  // goed, maar meteen daarna vond deze toets de twee weer GELIJK — de kaart
  // leent immers opnieuw, nu de groep — en leverde `null`. Gevolg: het
  // partijveld had niets om onder zijn combobox te tonen, de collectiekaart
  // verscheen nooit, en de afbakening van de zojuist gemaakte groep was
  // onbereikbaar. Precies de tweede helft van de eigenaarsbevinding, teruggekomen
  // via een omweg.
  //
  // Semantisch is dit ook de juiste kant op: ná de promotie WIJST deze regel naar
  // de groep, en een groep hoort zichtbaar te zijn op de plek waar zij bewerkt
  // wordt. Dubbel tonen levert het niet op: `IriVeld` zet de leesnode alleen
  // onder de combobox wanneer de waarde een COLLECTIE is (`isGroepWaarde`), en
  // een gedimd veld toonde zijn waarde altijd al.
  const lees = regel.assignee ? <Ref agent={regel.assignee} /> : null;
  return {
    sleutel: 'field.assignee',
    ref: regel.assignee?.iri,
    waarde: (
      <Veld spec={{
        term,
        soort: 'iri',
        preds: PRED.ASSIGNEE,
        iri: regel.assignee?.iri ?? null,
        categorie: 'parties',
        hint: tekst('edit.hintAfnemer'),
        nieuweGroep: true,
      }}
      >{lees}</Veld>
    ),
  };
}

/** DE NAAM-TAG VAN ÉÉN DOELOBJECT. Zij staat op twee plekken (een gewoon
 *  doelobject en de naam-tag die `<Collectie>` terugvraagt) en droeg die twee
 *  keer dezelfde JSX; sinds de target-route erbij komt zou dat drie dingen
 *  dubbel zijn. Vandaar één component.
 *
 *  TWEE BEWERKROUTES ERIN, allebei via een haak, want dit is een LEEScomponent:
 *   - de NAAM is een gewoon veld (`Veld`): in de kijkstand rendert hij letterlijk
 *     zijn kind, dus de leesweergave verandert er geen pixel van;
 *   - het ✕ (`targetKruis`) haalt dit doelobject uit de regel. */
function DoelTag(props: {
  tg: { label?: string | null; term?: unknown }; iri: string | null; regel: Regel;
}): JSX.Element {
  return (
    <span class="target-tag" title={props.iri || undefined} data-iri={props.iri || undefined}>
      <Veld spec={{
        term: props.iri || (props.tg as { term?: unknown }).term,
        soort: 'tekst',
        preds: PRED.TITEL,
        waarde: props.tg.label ?? '',
      }}
      >{props.tg.label}</Veld>
      <Haak naam="targetKruis" ctx={{ regel: props.regel, iri: props.iri }} />
    </span>
  );
}

/** De velden van een toestemming of verbod (permissionRow). Een verplichting
 *  heeft er één: haar actie, en alleen in de bewerkstand — zie `actieRij`.
 *
 *  GEEN "DOEL"-RIJ MEER (eigenaarsbesluit 8 sep 2026, letterlijk: "Doel in
 *  Actie/Doel/Doelobjecten mag dan weg wat mij betreft. Voelt niet generiek").
 *  De doelbinding is geen kaal veld op de regel maar een purpose-REFINEMENT op
 *  haar actie-knoop — ODRL 2.2-structuur, één voorwaarde tussen de andere. Zij
 *  stond hier als eigen rij én, sinds verbetering 5, als eerste rij van de
 *  Voorwaarden-sectie: dezelfde triples op twee plekken, met één bewerkroute die
 *  naar de andere plek wees ("De doelbinding bewerk je met het veld 'Doel'
 *  hierboven"). Nu staat zij op één plek, en wordt zij daar bewerkt — met de
 *  sloteditor, net als elke andere voorwaarde.
 *
 *  Het is een PARITEITSAFWIJKING: de bevroren viewer toont de rij wél
 *  (permissionRow, doc.js). Gelabelde verbetering, met het citaat als reden. */
function regelRijen(
  regel: Regel, soort: RegelSoort, eigenaar?: Partij | null,
  naam?: string | null, scope?: string | null,
): KvRij[] {
  const eigenTitel = regelTitel(regel, soort, naam);
  if (soort === 'duty') {
    const rij = bewerklaagActief() ? actieRij(regel, actie(regel), eigenTitel) : null;
    return rij ? [rij] : [];
  }
  const titel = eigenTitel;
  const a = actie(regel);
  // De afnemer alleen als hij AFWIJKT van die van de kaart: anders zou hij op
  // elke rij van dezelfde kaart herhaald worden.
  const eigenAfnemer = regel.assignee
    && (!eigenaar || regel.assignee.iri !== eigenaar.iri) ? regel.assignee : null;
  return [
    afnemerRij(regel, eigenAfnemer),
    // De actie expliciet in de body — tenzij hij al de titel van de rij ÍS. In
    // de bewerkstand staat hij er altijd, als veld; zie `actieRij`.
    actieRij(regel, a, titel) as KvRij,
    {
      sleutel: 'field.target',
      // IN DE BEWERKSTAND STAAT DE RIJ ER ALTIJD (fase C taak 5, de
      // target-route). Zonder die uitzondering is er op een regel zonder
      // doelobjecten geen plek waar de eerste kan ontstaan — dezelfde afweging
      // als bij de lege Voorwaarden-sectie en bij `actieRij`.
      waarde: ((regel.targets || []).length || bewerklaagActief()) ? (
        <span class="targets">
          {/* DE AANHECHTPLEK VAN DE DOELWITRIJ (14 sep 2026). Zie `KnoopKeten`
              in formulier.tsx: de open-sleutel is de keten van voorouders, en
              die moet bij de PLEK beginnen. Deze rij is één plek: de regel plus
              `#target`. Zonder haar deelt het doelwit van regel A zijn
              administratie met datzelfde doelwit op regel B, en klapt een
              herlading beide subbomen open waar de lezer er één opende. */}
          <KnoopKeten.Provider value={[`${rijSleutel(regel, scope)}#target`]}>
          <For each={regel.targets}>{(tg) => (
            <>
              {/* Is het doelobject een COLLECTIE, dan hoort haar ledenlijst
                  eronder én — bij een intensionele definitie — haar afbakening
                  (collectionNodes in de bevroren viewer; bevinding I-4).
                  <Collectie/> beslist welke van de drie vormen het is en
                  levert de naam-tag zelf terug.

                  DE COLLECTIEROUTE GAAT VOOR (eigenaarsvraag 11 sep 2026, de
                  doelwitvouw). Een collectie heeft al een eigen kaart met een
                  eigen uitklap; daar een tweede vouw omheen zetten levert twee
                  kaarten over hetzelfde ding. Alleen het GEWONE doelwit krijgt
                  de `KnoopVouw` — en die verdringt de naam-tag niet, hij komt
                  eromheen: de tag blijft letterlijk wat zij was, inclusief haar
                  ⌕ en haar bewerkroutes. Dekt geen formulier-shape het doelwit
                  (het gewone geval, en élk geval zonder profiel), dan rendert
                  `KnoopVouw` zijn kind en verandert er geen pixel. */}
              <Show
                when={isCollectie(tg as CollectieKnoop)}
                fallback={(
                  <KnoopVouw iri={tg.iri || null}>
                    <DoelTag tg={tg} iri={tg.iri || null} regel={regel} />
                  </KnoopVouw>
                )}
              >
                <Collectie
                  desc={tg as CollectieKnoop}
                  tag={(iri) => <DoelTag tg={tg} iri={iri} regel={regel} />}
                />
              </Show>
            </>
          )}</For>
          </KnoopKeten.Provider>
          {/* "+ gegevensset" sluit de rij af: daar komt de nieuwe tag te staan. */}
          <Haak naam="targetGhost" ctx={{ regel }} />
        </span>
      ) : null,
    },
    // De vindplaats sluit de rij af: eerst WAT de regel toestaat, dan waar hij
    // in het besluit staat. Bewust een EIGEN vorm naast de Grondslag
    // (`.src-loc`): dpv:hasLegalBasis zegt waaróp de regel rust, dct:source uit
    // welk stuk de verklaring komt, prov:hadPrimarySource wáár in dat stuk hij
    // staat — een verwijzing naar papier, geen normatieve bron.
    {
      sleutel: 'field.sourceLocation',
      waarde: (regel.primarySources || []).length
        ? <ProvRefs lijst={regel.primarySources} klasse="src-loc" /> : null,
    },
  ];
}

export interface RegelRijProps {
  regel: Regel;
  soort: RegelSoort;
  /** De afnemer van de kaart: staat hij ook op de regel, dan zwijgt de rij
   *  erover (permissionRow, ownerAssignee). */
  eigenaar?: Partij | null;
  /** Het kleine gedempte herkomstwoordje achter de naam ("aanvullend"), dat de
   *  plichtenlaag meegeeft (viewer: `extra`/`mark` in obligationRow). */
  merk?: string | null;
  /** De IRI van de KAART waar deze rij in staat. Het invulling-paneel gebruikt
   *  hem om bij een gedeelde regel de juiste kaart voorrang te geven. */
  scope?: string | null;
  /** De naam die de GROEPERING voor deze rij afleidde (de waarde van het
   *  binnenste niveau); alleen gebruikt als de regel geen eigen titel heeft. */
  naam?: string | null;
  /** De dimensies die de omhullende groepsrijen al tonen (`shownDims`). Sinds
   *  het vervallen van de Doel-rij stuurt hij de VOORWAARDEN-sectie: een
   *  doelbindingsrij zwijgt in de LEESstand zodra het niveau erboven haar al
   *  zegt. Zie `voorwaardeLijst`. */
  getoondeDims?: string[];
  /** De knoop waaronder deze rij getekend staat: de kaart, of de regel waar
   *  deze plicht onder hangt. De bewerklaag gebruikt hem als VOORKEUR bij het
   *  zoeken van de koppeling die het ✕ en het ⧉ verbreken — zonder hem is een
   *  gedeelde plicht niet los te maken zonder te gokken welke van haar ouders
   *  bedoeld is. De leesweergave doet er niets mee. */
  ouder?: unknown;
}

export function RegelRij(props: RegelRijProps): JSX.Element {
  const titel = () => regelTitel(props.regel, props.soort, props.naam);
  const sleutel = () => rijSleutel(props.regel, props.scope);
  const rijen = () => regelRijen(
    props.regel, props.soort, props.eigenaar, props.naam, props.scope,
  );
  const parameters = () => (props.soort === 'duty'
    ? plichtParameters(props.regel, bewerklaagActief()) : '');
  // "GEEN PARAMETERS" BLIJFT DE KIJKSTAND-VRAAG. Zou hij `parameters()`
  // gebruiken, dan zou een verplichting die in de bewerkstand haar actie naar de
  // Actie-rij verhuist ineens "geen parameters" melden terwijl er niets
  // veranderde. De mededeling gaat over de DATA, niet over de stand.
  const alleParameters = () => (props.soort === 'duty' ? plichtParameters(props.regel) : '');
  const geenParameters = () => props.soort === 'duty' && !alleParameters()
    && !(props.regel.constraints || []).length && !(props.regel.refinements || []).length
    && !(props.regel.duties || []).length;
  // DE KNOOP HOORT MEE. `extraRijen` zonder tweede argument levert LEESVORM —
  // dat is de stand voor de verkenner en het invulling-paneel, die geen
  // bewerkroute hebben. De regelrij hoort bij de kaart en niet bij die twee:
  // haar overige eigenschappen (de `dct:identifier` van een regel voorop) waren
  // in de bevroren viewer bewerkbaar via de actie-strook, en werden hier een
  // kale span — de enige vermogensdelta van de C2-einddoorloop die geen
  // vormkwestie was. Dezelfde knoopuitdrukking als de titel-Veld hieronder: een
  // benoemde regel wordt op haar IRI geadresseerd, een blanke op haar term.
  const knoop = () => props.regel.iri || (props.regel as { term?: unknown }).term;
  // DE AANHECHTPLEK VAN DEZE REGELRIJ, en met opzet niet `knoop()`: dezelfde
  // regel wordt op TWEE kaarten getekend (een aanbodregel staat ook onder de
  // overeenkomst die hem invult), en dan is de regel-IRI geen plek maar een
  // knoop. `rijSleutel` is de identiteit die deze rij zelf al gebruikt —
  // scope plus regel — en dus precies wat een vouw hieronder nodig heeft.
  const extra = () => extraRijen(
    props.regel.extraProps, knoop(), rijSleutel(props.regel, props.scope),
  );
  // DE DEKKINGSMEDEDELING op de kop van een regelrij, met alle drie de takken
  // van `coverageStatusChip` (doc.js r.5175-5200) — de conditie was eerder
  // alleen `inConformsContext`, en dat gaf op vlierdam 11 raderwielen tegen 9
  // in de bevroren viewer, plus 0 merken tegen 2:
  //   1. buiten een conformsToPolicy-context: niets (het paneel zou niets te
  //      vertellen hebben);
  //   2. ORGANISATORISCH geborgd (dpv:OrganisationalMeasure op de regel): het
  //      gedempte merk en géén raderwiel — er valt niets open te klappen;
  //   3. anders: een raderwiel, en alleen als er een VOLGENDE STAP is. Niet de
  //      status bepaalt dat, maar de keten (inclusief de transitieve invulling
  //      via een scherpere voorwaarde elders).
  const dekking = () => (props.regel as { coverage?: Dekking | null }).coverage;
  const inDekkingsContext = () => !!dekking()?.inConformsContext;
  const organisatorisch = () => inDekkingsContext() && !!dekking()?.organisational;
  // `nextSteps` filtert op `targetRef` (doc.js r.4232): een stap zonder adres
  // is niets om naartoe te klappen. Zonder dat filter zou hier een ⚙ staan waar
  // de bevroren viewer zwijgt (op vlierdam maakt het niets uit — 9 = 9 — maar
  // exact is exact).
  const heeftVolgendeStap = () => (coverageNext(props.regel) as { targetRef?: string }[])
    .some((x) => x && x.targetRef);
  const toontRaderwiel = () => !!props.regel.iri && inDekkingsContext()
    && !organisatorisch() && heeftVolgendeStap();
  // Hoe een GENESTE rij (een plicht, een gevolg) getekend wordt: als dezelfde
  // component, met dezelfde eigenaar-onderdrukking en het merk dat de
  // plichtenlaag meegeeft.
  const rij: RijBouwer = (r, soort, merk) => (
    <RegelRij
      regel={r} soort={soort} merk={merk}
      eigenaar={props.eigenaar} scope={props.scope}
      ouder={props.regel}
    />
  );
  // De drie secties tellen MEE: een rij die alleen voorwaarden, plichten of
  // gevolgen draagt is geen blad, en zou zonder deze telling ten onrechte
  // `op-leaf` krijgen (en dus geen uitklap). `geenParameters()` blijft zoals hij
  // is: die telt constraints en refinements al.
  // Als MEMO: `inhoud()` wordt per uitlezing geëvalueerd en zou de
  // voorwaardenlijst telkens opnieuw platslaan — dezelfde getter-val die de
  // kaartenlijst 157 s kostte (bevinding N-4). `Voorwaarden` doet dit werk zelf
  // ook al in een memo.
  const voorwaarden = createMemo(() => voorwaardeLijst(props.regel, props.getoondeDims));
  // In de BEWERKSTAND tellen de (nog) lege secties mee: een regel die nog geen
  // voorwaarde of plicht heeft, moet wel een plek hebben om de eerste toe te
  // voegen — zelfde afweging als `constraintsSection` in de bevroren viewer.
  const secties = () => !!voorwaarden().length
    || !!(props.regel.duties || []).length
    || !!((props.regel as { consequences?: unknown[] }).consequences || []).length
    || bewerklaagActief();
  const inhoud = () => !!props.regel.description || !!parameters() || geenParameters()
    || !!extra().length || secties() || rijen().some((r) => r.waarde != null && r.waarde !== '');
  return (
    <details
      // Ook de RIJ is een onthuller (review I-1): de plicht- en
      // voorwaarde-ghosts in haar body horen bij deze rij, niet bij de kaart als
      // geheel. Nesten is onschadelijk — een hover op de kaart onthult alles
      // erin, een hover op de rij alleen wat in de rij staat.
      class={'op-row ' + props.soort + (inhoud() ? '' : ' op-leaf') + ghostOnthulKlasse()}
      // data-iri: de generieke stempel waarop een sprong binnen de pagina een
      // rij terugvindt. data-ref is hetzelfde adres, maar als contract: het
      // invulling-paneel en de dekkingsuitklap wijzen erop. Een blanke regel
      // heeft geen knoop om naartoe te springen en draagt geen van beide.
      data-iri={props.regel.iri || undefined}
      data-ref={props.regel.iri || undefined}
      // DE OPEN-STAND UIT HET SIGNAAL, niet uit de DOM (eis 1 van het
      // eigenaarsbesluit). Zie `rijSleutel` bovenaan dit bestand voor het
      // waarom; zonder sleutel leest `staatRijOpen` het signaal niet en gedraagt
      // de rij zich als een gewone <details>.
      open={staatRijOpen(sleutel())}
      onToggle={(e) => zetRijOpen(sleutel(), e.currentTarget.open)}
    >
      <summary class="op-summary" {...kopBediening()}>
        <RegelBadge soort={props.soort} />
        {/* FAMILIE 1 van de kopieerveeg (9 sep 2026), en met 37 rijen op het
            demo-corpus de grootste: tussen de regelbadge en de titel stond
            alleen de `gap: 12px` van `.op-summary`. Geplakt las een regelrij als
            "verplichtingProtocolleringsplicht". De ruimte gaat in kaart.css uit
            de stroom, dus de 12px blijft 12px. */}
        <ChipRuimte />
        <span class="op-title" title={titel()}>
          {/* DE NAAM VAN DE RIJ IS HET EERSTE ✎ VAN HET NIEUWE ELEMENT (eis 2
              van het eigenaarsbesluit 8 sep 2026: "je springt direct naar het
              nieuwe item in edit mode, titel editable at least"). Dezelfde
              veldroute als de kaarttitel — `Veld` rendert in de kijkstand
              letterlijk zijn kind, dus de leesweergave verandert er geen pixel
              van, en er komt geen tweede bewerkmechanisme naast.

              `waarde` is de GETOONDE naam en niet alleen de eigen dct:title: de
              bewerkvorm toont wat het veld draagt, en met een lege waarde zou
              een regel die zijn naam van zijn actie leent in de bewerkstand
              naamloos worden. Een save die niets verandert wordt overgeslagen
              (zie `TekstVeld`), dus dit materialiseert geen titel die er niet
              stond; wie de tekst wél aanpast, bedoelt precies dat.

              `dragendPred` kiest tussen dct:title en rdfs:label — een
              verplichting draagt haar naam op de tweede (zo leest parse.js hem,
              zo schrijft `addDuty` hem). */}
          <span class="op-name">
            <Veld spec={{
              term: props.regel.iri || (props.regel as { term?: unknown }).term,
              soort: 'tekst',
              preds: PRED.TITEL,
              waarde: titel(),
              // DE HINT VAN EEN NAAMLOZE RIJ (9 sep 2026, tweede ronde). `titel()`
              // is de GETOONDE naam en die is bij een verse rij afgeleid — van de
              // regelsoort ("Toestemming", "Verbod") of van de actie
              // ("Informeren", sinds `addDuty` geen rdfs:label "Nieuwe
              // verplichting" meer schrijft). Die afleiding blijft in de KOP
              // staan; het invoerveld staat leeg met deze hint. Zie `TekstVeld`.
              hint: tekst('edit.hintNaam'),
              focusSleutel: focusAdres((props.regel as { term?: unknown }).term
                ?? props.regel.iri),
            }}
            >{titel()}</Veld>
          </span>
          {/* EEN BLANKE REGEL KAN HIER EEN NAAM KRIJGEN (eigenaarsrichting 9 sep
              2026: "En hoe we bestaande nodes kunnen 'namen' natuurlijk").
              Dezelfde chip en dezelfde mutatie (`benoemKnoop`) als op de
              kaartkop, en zij hoort júist hier: een blanke regel is buiten dit
              document niet aan te wijzen, en dat is precies wat de hergebruik-
              route van de sectiechip als reden opgeeft ("een blanke regel is niet
              aan te wijzen; geef hem eerst een naam"). Een BENOEMDE regel draagt
              zijn IRI al in zijn merk en krijgt er geen tweede weergave bij.
              In de KIJKSTAND rendert `Veld` letterlijk zijn kinderen — hier geen
              — dus daar verandert er geen pixel. */}
          <Show when={!props.regel.iri && (props.regel as { term?: unknown }).term}>
            <Veld spec={{
              term: (props.regel as { term?: unknown }).term,
              soort: 'iri',
              preds: [],
              vorm: 'knoopIri',
              iri: null,
            }}
            />
          </Show>
          {/* FAMILIE 5 van de kopieerveeg: het merk staat naast de naam in een
              `.op-title` met `gap: 10px`, en plakte als
              "Registratie van laadpalenvlierdam:…". */}
          <Show when={props.merk}>{(m) => (
            <><ChipRuimte /><span class="op-path muted">{m()}</span></>
          )}</Show>
        </span>
        {/* Zie `dekking()` hierboven: merk óf raderwiel, nooit allebei. */}
        <Show when={organisatorisch()}>
          <ChipRuimte />
          <span class="cov-organisational muted" title={tekst('cov.organisationalRuleTitle')}>
            {tekst('cov.organisational')}
          </span>
        </Show>
        <Show when={toontRaderwiel()}>
          <ChipRuimte />
          <InvullingKnop doel={props.regel.iri!} scope={props.scope ?? null} />
        </Show>
        {/* HET ⌕ VAN DE REGELRIJ (bevinding C-1), NA het raderwiel: op een
            regelkop zet de bevroren viewer eerst `coverageStatusChip` en dan
            `verkenBtn` (permissionRow doc.js r.6392-6395, dutyRow r.5257-5258).
            Op een VOORWAARDE-rij is de volgorde precies andersom (⌕ dan ⚙, zie
            voorwaardeStrook) — die twee zijn gemeten en niet aangenomen. Een
            blanke regel heeft geen adres en krijgt geen ⌕. */}
        <ChipRuimte />
        {/* DE ACTIESTROOK van deze rij, ná de kijk-iconen: dezelfde volgorde
            als in de bevroren viewer (regelStrook staat rechts van ⚙ en ⌕) en
            vóór de chevron, die de rechterrand houdt. */}
        <Haak
          naam="regelStrook"
          ctx={{
            regel: props.regel, soort: props.soort, ouder: props.ouder,
            scope: props.scope ?? null,
          }}
        />
        <Chevron />
      </summary>
      <Show when={inhoud()}>
        <div class="op-body">
          {/* Bevinding I-5: ook een regelbeschrijving wordt boven 600 tekens
              afgekapt (beschrijvingVeld -> longText in de bevroren viewer). */}
          <Show when={props.regel.description}>{(d) => (
            <p class="rule-desc"><LangeTekst tekst={d()} /></p>
          )}</Show>
          <Show when={parameters()}>{(s) => <p class="duty-sub">{s()}</p>}</Show>
          <Show when={geenParameters()}>
            <p class="duty-sub muted">{tekst('duty.noParams')}</p>
          </Show>
          <Kv rijen={rijen()} />
          {/* De volgorde van permissionRow/obligationRow in de bevroren viewer:
              eerst waar de regel over gaat (voorwaarden), dan wat zij oplegt
              (plichten), dan wat er gebeurt als dat niet gebeurt (gevolgen). */}
          <Voorwaarden
            regel={props.regel}
            scope={props.scope}
            getoondeDims={props.getoondeDims}
          />
          <Plichten regel={props.regel} rij={rij} soort={props.soort} />
          <Gevolgen regel={props.regel} rij={rij} />
          <Show when={extra().length}>
            <h4>{tekst('head.otherProps')}</h4>
            <Kv rijen={extra()} />
          </Show>
        </div>
      </Show>
    </details>
  );
}

// --- De groepsrijen ---------------------------------------------------------

const TELWOORD: Record<string, string> = {
  toestemming: 'noun.permission', verbod: 'noun.prohibition', duty: 'noun.duty',
};

/** Het telwoord bij een groepskop: in het regeltype-woord zelf ("5
 *  toestemmingen"), zodat de kop meteen zegt hoeveel van WAT eronder hangt. Is
 *  een groep gemengd, dan valt het terug op het neutrale "n regels". */
export function groepTelling(regels: Regel[], soort: RegelSoort): string {
  const soorten = new Set(regels.map((r) => (r.kind === 'duty' ? 'duty' : soort)));
  return soorten.size === 1
    ? tekst(TELWOORD[[...soorten][0]] || 'rules.count', { n: regels.length })
    : tekst('rules.count', { n: regels.length });
}

/** Eén knoop uit `groepeer()`: een gewone regelrij, of een NIVEAU met zijn
 *  kinderen eronder.
 *
 *  De groepsrij benoemt het niveau met het label van de DIMENSIE (dat komt uit
 *  de data, niet uit code) en draagt de kleur van het regeltype eronder. Ook een
 *  niveau met precies één regel krijgt die kaart: zodra de bron een dimensie
 *  DECLAREERT, hoort dezelfde structuur er overal hetzelfde uit te zien. */
export function Regelknoop(props: {
  knoop: Groepknoop;
  soort: RegelSoort;
  eigenaar?: Partij | null;
  scope?: string | null;
  /** De dimensies die de rijen hierboven al tonen. */
  getoondeDims: string[];
  /** De KNOOP WAARONDER deze rij getekend staat — op dit niveau de kaart. Zie
   *  `RegelRijProps.ouder`: de bewerklaag gebruikt hem als voorkeur bij het
   *  zoeken van de koppeling die het ✕ en het ⧉ verbreken. Hij kwam op
   *  kaartniveau nooit aan (review I-3), waardoor een regel die vanuit twee
   *  beleidsstukken wordt aangehaald zijn ⧉ en ✕ verloor — terwijl de kaart
   *  waarop je kijkt de koppeling gewoon aanwijst. De bevroren viewer gaf hem
   *  aan élke kaartrij mee (doc.js r.6866, 7949, 8426). Een GROEPEERNIVEAU
   *  reikt hem door: het niveau is een weergave-constructie, de kaart eronder
   *  blijft de ouder van de rijen. */
  ouder?: unknown;
}): JSX.Element {
  return (
    <Show
      when={props.knoop.kind === 'group' ? props.knoop : null}
      fallback={(
        <RegelRij
          regel={(props.knoop as { rule: Regel }).rule}
          soort={props.soort}
          eigenaar={props.eigenaar}
          scope={props.scope}
          // Alleen de NAAM komt uit de groep (de waarde van het binnenste
          // niveau); het woord op de chip is en blijft het regeltype.
          naam={(props.knoop as { label: string | null }).label}
          getoondeDims={props.getoondeDims}
          ouder={props.ouder}
        />
      )}
    >{(groep) => {
      const dieper = () => [...props.getoondeDims, groep().dim.iri];
      const groepSleutel = () => {
        const w = groep().value.iri || groep().value.label || '';
        return w ? `groep:${props.scope || ''}|${groep().dim.iri}|${w}` : '';
      };
      const curie = () => {
        const c = groep().value.curie;
        return c && !/^https?:/.test(c) ? c : null;
      };
      /** DE WAARDE VAN DIT NIVEAU ALS KNOOP — of null als er geen knoop is.
       *
       *  `value.iri` is niet altijd een IRI: `ruleDimensions` (parse.js) valt op
       *  de doelbinding terug op `p.iri`, en die draagt bij een LITERALE
       *  rechteroperand de literal zelf ("los doel"). Een naamveld daarop zou een
       *  knoop bewerken die niet bestaat. Een knoop-IRI heeft een schema; die
       *  toets staat hier lokaal en niet via `geldigeIriTekst` uit
       *  `model/velden.js`, want die module trekt de serialisatielaag (13,6 kB)
       *  de leeschunk in — zie de kop van `ui/bewerk/haken.tsx`. */
      const waardeKnoop = () => {
        const i = groep().value.iri;
        return i && /^[a-z][a-z0-9+.-]*:/i.test(i) ? i : null;
      };
      return (
        <details
          // `ghostOnthulKlasse()`: sinds dit niveau zijn EIGEN ghost draagt (eis
          // 5) hoort het ook een onthuller te zijn — anders staat die ene ghost
          // permanent aan terwijl alle andere gedimd zijn tot de muis erbij komt,
          // en dat is precies de ongelijkheid die de dichtheidsregel wegneemt.
          class={'op-row ' + props.soort + ' niveau' + ghostOnthulKlasse()}
          data-iri={groep().value.iri || undefined}
          // Ook een GROEPEERNIVEAU bewaart zijn stand buiten de DOM (eis 1): hij
          // wordt bij dezelfde gerichte herbouw hertekend als de rijen eronder.
          // Zijn adres is dimensie + waarde binnen de kaart — een groepsrij heeft
          // geen eigen knoop, dus er valt niets anders aan te wijzen.
          open={staatRijOpen(groepSleutel())}
          // MEESCROLLEN: een groepsrij kan een halve kaart aan regels bevatten
          // en staat vaak onderin beeld. Zij is daarom, náást de kaart zelf, de
          // tweede plek waar de pagina meeschuift met wat de lezer opent —
          // dezelfde verzameling als `isExpandScrollTarget` in de bevroren
          // viewer (`.agr-group`, `.offer-group`, `.op-row.niveau`). Losse
          // regelrijen niet: die zijn klein genoeg om zonder sprong te lezen.
          onToggle={(e) => {
            zetRijOpen(groepSleutel(), e.currentTarget.open);
            if (e.currentTarget.open) meescrollNaUitklap(e.currentTarget);
          }}
        >
          <summary class="op-summary" {...kopBediening()}>
            {/* Een PLATTE chip, geen <RegelBadge>: die draagt de uitleg van de
                ODRL-klasse waar haar woord voor staat, en hier staat een
                dimensienaam uit de data. De uitleg van "toestemming" hoort niet
                achter het woord "Doel". */}
            <span class={'method ' + props.soort}>{groep().dim.label || groep().dim.iri}</span>
            {/* Familie 1 geldt ook voor de PLATTE chip van een groepeerniveau:
                zelfde `.op-summary`, zelfde gap, zelfde plakprobleem. */}
            <ChipRuimte />
            <span class="op-title" title={groep().value.label}>
              {/* DE NAAM VAN DE GROEPEERWAARDE IS BEWERKBAAR (eigenaarsbevinding
                  9 sep 2026, letterlijk: "Ik kan de naam van het doel nu
                  helemaal nergens editen").

                  Sinds de Doel-rij verviel (besluit 1e) bewerkt de sloteditor
                  WELK doel op een regel staat; de NAAM van de doelknoop zelf had
                  daarna nergens meer een plek. Die plek is deze kop: het vakje
                  waar de regels van dat doel onder hangen is precies het element
                  dat de naam TOONT, en de regel van dit hele deeltraject is dat
                  je bewerkt waar je leest.

                  DEZELFDE VELDROUTE als de kaarttitel en de rijnaam — `Veld`
                  rendert in de kijkstand letterlijk zijn kind, dus de
                  leesweergave verandert er geen pixel van, de save loopt via
                  `zetLiteral` (alleen de getoonde taal, één undo-stap) en een
                  doeldefinitie uit een andere bron krijgt het gewone gelockte ✎
                  met zijn reden. Geen tweede mechanisme.

                  NIET ALLEEN VOOR HET DOEL: elke groepeerdimensie die op een
                  IRI-waarde indeelt krijgt hem hiermee, want de kop is er één.
                  Dat is de "gratis meekomt"-tak van de brief; een dimensie
                  waarvan de waarde géén knoop is (een kale literal- of
                  curie-waarde) heeft niets te benoemen en krijgt het gedimde ✎
                  met `edit.groepWaardeGeenKnoop`. */}
              <span class="op-name">
                <Veld spec={{
                  term: waardeKnoop(),
                  soort: 'tekst',
                  preds: PRED.NAAM,
                  waarde: groep().value.label ?? '',
                  hint: tekst('edit.hintNaam'),
                  label: groep().dim.label || groep().dim.iri,
                  nvt: waardeKnoop() ? undefined : tekst('edit.groepWaardeGeenKnoop'),
                }}
                >{groep().value.label}</Veld>
              </span>
              {/* Familie 5 van de kopieerveeg: de curie staat naast de waarde in
                  een `.op-title` met `gap: 10px`. Dit is de plek die de veeg als
                  "Registratie van laadpalenvlierdam:…" mat. */}
              <Show when={curie()}>{(c) => (
                <><ChipRuimte /><span class="op-path mono muted">{c()}</span></>
              )}</Show>
            </span>
            <ChipRuimte />
            <span class="op-sum muted">{groepTelling(groep().rules, props.soort)}</span>
            {/* Ook een GROEPEERNIVEAU wijst een knoop aan — de waarde van de
                dimensie — en draagt dus zijn ⌕ (doc.js r.6822). */}
            <ChipRuimte />
            {/* Een GROEPEERNIVEAU heeft geen eigen knoop in de graaf: de strook
                staat er wel, met alle vier de iconen uit en de reden erin. Dat
                is de kop≠sectie-regel van taak 9f — de rijen van een kaart
                horen er allemaal hetzelfde uit te zien. */}
            <Haak
              naam="regelStrook"
              ctx={{
                regel: { iri: null } as Regel, soort: props.soort, afgeleid: true,
                scope: props.scope ?? null,
              }}
            />
            <Chevron />
          </summary>
          <div class="op-body">
            <div class="op-list">
              <For each={groep().children}>{(kind) => (
                <Regelknoop
                  knoop={kind}
                  soort={props.soort}
                  eigenaar={props.eigenaar}
                  scope={props.scope}
                  getoondeDims={dieper()}
                  ouder={props.ouder}
                />
              )}</For>
              {/* DE GHOST VAN DÍT NIVEAU (eigenaarsbesluit 8 sep 2026, eis 5):
                  in een dimensie-weergave hoort er ook binnen een vakje iets toe
                  te voegen te zijn, en wat je daar toevoegt hoort de voorwaarde
                  van dat vakje al te dragen — anders valt het meteen buiten de
                  groep waarin je het maakte. Hij staat als LAATSTE in de
                  `op-list` van dit niveau, om dezelfde reden als de kaart-ghost:
                  daar landt het resultaat. Alleen op het BINNENSTE niveau, want
                  daar is de indeling volledig; op een tussenniveau zou de nieuwe
                  regel meteen in een dieper vakje verdwijnen dat de lezer niet
                  aanwees. */}
              <Show when={!groep().children.some((k) => k.kind === 'group')}>
                <Haak
                  naam="groepGhost"
                  ctx={{
                    pol: props.ouder as Policy,
                    soort: props.soort,
                    dimIri: groep().dim.iri,
                    waardeIri: groep().value.iri ?? null,
                    waardeLabel: groep().value.label ?? null,
                  }}
                />
              </Show>
            </div>
          </div>
        </details>
      );
    }}</Show>
  );
}

/** De regels van één kaart, in leesvolgorde: verplichtingen (wat er moet),
 *  toestemmingen (wat er mag) en verboden (wat niet mag). Dezelfde volgorde
 *  als fillOfferSection in de bevroren viewer. */
export function regelLijst(pol: Policy): { regel: Regel; soort: RegelSoort }[] {
  return [
    ...(pol.obligations || []).map((r) => ({ regel: r, soort: 'duty' as RegelSoort })),
    ...(pol.permissions || []).map((r) => ({ regel: r, soort: 'toestemming' as RegelSoort })),
    ...(pol.prohibitions || []).map((r) => ({ regel: r, soort: 'verbod' as RegelSoort })),
  ];
}

export function Regels(props: {
  pol: Policy; soort?: Kaartsoort; eigenaar?: Partij | null;
}): JSX.Element {
  const rijen = () => regelLijst(props.pol);
  // De AFNEMER VAN DE KAART, zodat de rijen hem niet allemaal herhalen. Op een
  // AANBOD niet: daar is er geen afnemer op de policy, en de afnemer op een
  // regel is dan juist het onderscheidende feit (fillOfferSection geeft
  // ownerAssignee bewust niet mee).
  const eigenaar = () => {
    if (props.eigenaar !== undefined) return props.eigenaar;
    return props.soort === 'offer' ? null : (policyAssignee(props.pol) as Partij | null);
  };
  // De rijbouwer die de overervings- en aanbodlaag gebruiken voor hun eigen
  // geneste rijen.
  const rij: RijBouwer = (r, soort, merk) => (
    <RegelRij
      regel={r} soort={soort} merk={merk} eigenaar={eigenaar()} scope={props.pol.iri}
      // DE KAART IS DE OUDER van elke rij die zij tekent (review I-3). Ook van
      // een GEËRFDE of via een aanbod getoonde rij: die hangt daar niet onder, en
      // dan vindt `knoopAnker` de voorkeur eenvoudig niet en valt terug op zijn
      // "maar één kandidaat"-tak. Faalt veilig, en levert op de gewone kaartrij
      // precies de koppeling op die de lezer aanwijst.
      ouder={props.pol}
    />
  );
  // DE EIGEN REGELS ALS BLOKKEN, elk apart gegroepeerd — precies waar de
  // bevroren viewer `ruleRows` aanroept (doc.js r.6897/6900, 7950/7951,
  // 8434/8435): op de eigen toestemmingen en, apart, op de eigen verboden. De
  // geërfde rijen en de aanbodvouw krijgen géén groepering; daar bouwt de
  // bevroren viewer zijn rijen rechtstreeks met `permissionRow`.
  // "OP AANBOD:" — vult deze policy meer dan één aanbod in, dan worden haar
  // eigen TOESTEMMINGEN per aanbod ingedeeld (agreementOps in de bevroren
  // viewer). De verboden blijven daarbuiten: die indeling gaat over wat er uit
  // welk aanbod mag, niet over wat er niet mag.
  const secties = createMemo(() => aanbodSecties(props.pol));
  const knopenVan = (soort: RegelSoort) => {
    void actieveDimensies();                 // reactief op de groepeerkeuze
    return groepeer(eigenRegels(props.pol)
      .filter((r) => r.soort === soort).map((r) => r.regel));
  };
  // Vult deze policy meer dan één aanbod in, dan zitten haar toestemmingen in de
  // subsecties en niet in een eigen blok — anders zouden ze er twee keer staan.
  const toestemmingKnopen = createMemo(() => (secties() ? [] : knopenVan('toestemming')));
  const verbodKnopen = createMemo(() => knopenVan('verbod'));
  const plichten = createMemo(() => eigenPlichten(props.pol));

  // --- DRIE GETYPEERDE SECTIES, ELK MET ZIJN EIGEN TOEVOEGCHIP ---------------
  //
  // EIGENAARSBESLUIT 9 SEP 2026, in twee delen en letterlijk:
  //
  //   "Je hebt in de regels nu een volgorde van verplichtingen, toestemming,
  //    verboden maar de add chips (+ toestemming + verbod + verplichting) staan
  //    allemaal onderaan. Bij die volgorde zie je de chips dus niet inline
  //    verschijnen. Zet meer een regel brede add-chip per sectie dan; dus
  //    verplichting 1 / verplichting 2 / + verplichting — toestemming 1 /
  //    + toestemming — etc"
  //
  //   "Het is dan ook logischer dat de generieke 'Rules' sectie wordt
  //    opgesplitst in Duty, Permission en Prohibition secties."
  //
  // De volgorde die er al was blijft: verplichtingen (wat er moet),
  // toestemmingen (wat er mag), verboden (wat niet mag) — dezelfde als
  // `regelLijst` en als fillOfferSection in de bevroren viewer. Wat erbij komt
  // is dat elke soort nu zijn eigen KOP heeft en zijn eigen chip als laatste
  // rij, zodat het nieuwe element direct bóven die chip verschijnt.
  //
  // PARITEITSAFWIJKING, gelabelde verbetering: de bevroren viewer zet alle
  // regels van een kaart onder één kop "Regels" (setCardBody). Die kop is hier
  // niet meer, ook niet als umbrella — eigenaarsbesluit 9 sep 2026: "Die REGELS
  // moet weg nu het opgesplitst is." De drie sectiekoppen NEMEN zijn plaats in
  // (en zijn niveau: `h3`), ze hangen er niet meer onder.
  //
  // WAT NIET IN EEN SECTIE PAST, en waarom dat boven de drie staat: de
  // HERKOMSTlagen. `<GeerfdVouw>` en `<AanbodVouw>` vouwen regels van álle drie
  // de soorten samen in één rij ("Geërfd van ‹ouder› (3 regels)", "Uit het
  // aanbod (4 verplichtingen, 1 toestemming)"). Zo'n rij heeft geen soort, dus
  // geen sectie; zij benoemt zichzelf en heeft geen kop nodig. Sinds de umbrella
  // verviel staan zij kopeloos bovenaan het regelblok; wat hen van de kv-rijen
  // van de kaartbody scheidt is de marge die kaart.css op zo'n lijst zet, niet
  // langer de onderlijn van een kop.
  const heeftSectie = (s: RegelSoort): boolean => {
    if (s === 'duty') return plichten().regels.length > 0;
    if (s === 'toestemming') {
      return secties() ? (secties() as unknown[]).length > 0 : toestemmingKnopen().length > 0;
    }
    return verbodKnopen().length > 0;
  };
  const sectieGhost = (s: RegelSoort): JSX.Element => (
    <Haak
      naam="kaartGhost"
      ctx={{ pol: props.pol, soort: props.soort, soorten: [s], plaatsing: 'sectie' }}
    />
  );
  /** De kop van één getypeerde sectie. Hij staat er ALLEEN als de sectie regels
   *  heeft — een kop zonder inhoud is de C-1-fout, in kijk- én in bewerkstand
   *  (`legeKoppen` in `ghost-plek.test.tsx` telt er 44 op het demo-corpus toen
   *  die poort ontbrak). Waar de chip dan woont zegt `zonderSectie` hieronder.
   *
   *  `h3` sinds het eigenaarsbesluit van 9 sep 2026: dit is de bovenste kop van
   *  een kaart geworden, want de "Regels"-umbrella waar hij als `h4` onder hing
   *  bestaat niet meer. Zie de kop van dit bestand voor de niveaus. De
   *  KLASSENAAM `regels-subkop` blijft — hij is nog steeds een kop BINNEN een
   *  kaart, en hij is het DOM-adres van drie toetsen plus het e2e-geval
   *  `toevoegfocus.mjs`. */
  const SectieKop = (p: { soort: RegelSoort; sleutel: string }): JSX.Element => (
    <TermKop tag="h3" sleutel={p.sleutel} class={`regels-subkop ${p.soort}`} />
  );
  // RULING (lane-sectiechips, keuze 2 van de brief). De soorten waarvan deze
  // kaart nog GEEN enkele regel heeft, houden hun chip in het compacte blok
  // onderaan. Alternatief zou een lege sectiekop zijn om de chip in te hangen —
  // en dat is precies de C-1-familie ("geen koppen zonder inhoud in kijk- óf
  // bewerkstand", `legeKoppen` in ghost-plek.test.tsx). Zo houdt elke soort
  // altijd precies één toevoegplek: in zijn sectie zodra die bestaat, en anders
  // onderaan.
  const zonderSectie = createMemo(
    () => (['duty', 'toestemming', 'verbod'] as RegelSoort[]).filter((s) => !heeftSectie(s)),
  );
  // ZICHTBAARHEID via toontRegels, TELLING via telRegels op de kaartkop — en
  // die twee lopen bewust uiteen: een policy die alleen ERFT stelt zelf geen
  // regels (kop blijft leeg) maar toont wel wat er geldt. Zie de fixronde van
  // taak 5; dit is geen bug om gelijk te trekken.
  // ZICHTBAARHEID in de BEWERKSTAND: een kaart zonder regels krijgt haar
  // regellijst alsnog, want daar staat de ghost waarmee de eerste regel ontstaat
  // (viewer: `if (ops.children.length)` — de ghost telt daar mee).
  return (
    <Show when={toontRegels(props.pol) || bewerklaagActief()}>
      {/* GEEN KAARTBREDE "Regels"-KOP MEER — eigenaarsbesluit 9 sep 2026, dat de
          eerdere lane-ruling omdraait: "Je hebt nu én REGELS én
          VERPLICHTINGEN/TOESTEMMINGEN kopjes. Die REGELS moet weg nu het
          opgesplitst is." Twee dingen hingen eronder, en die staan nu op eigen
          benen. (1) De HERKOMSTlagen hieronder hebben geen soort en dus geen
          getypeerde sectie; zij benoemen zichzelf in hun rijtekst ("Geërfd van
          ‹ouder› (3 regels)") en staan kopeloos boven de secties — de
          scheiding van de kaartbody eronder komt van `.op-list:has(...)` in
          kaart.css, niet van een kop. (2) Het verzamelblok onderaan draagt
          alleen chips, en die benoemen zichzelf ("+ toestemming"). Een kaart
          zonder één regel toont dus géén kop — precies de C-1-regel. */}
      {/* De gelaagde volgorde van setCardBody/agreementOps: eerst wat van boven
          komt (overerving), dan wat het aanbod doorgeeft, en pas daarna wat deze
          policy zelf oplegt, toestaat en verbiedt. */}
      <GeerfdVouw pol={props.pol} rij={rij} />
      <AanbodVouw pol={props.pol} rij={rij} />

      {/* --- 1. VERPLICHTINGEN (odrl:obligation) ------------------------- */}
      <Show when={heeftSectie('duty')}>
        <SectieKop soort="duty" sleutel="head.obligations" />
        <div class="op-list">
          <For each={plichten().regels}>{(d) => (
            // "aanvullend" zodra het AANBOD zelf al verplichtingen levert: dan
            // staan er twee lijstjes en moet de lezer weten welk bovenop het
            // andere komt.
            rij(d, 'duty', plichten().aanvullend ? tekst('offerRules.extra') : null)
          )}</For>
          {sectieGhost('duty')}
        </div>
      </Show>

      {/* --- 2. TOESTEMMINGEN (odrl:permission) -------------------------- */}
      <Show when={heeftSectie('toestemming')}>
        <SectieKop soort="toestemming" sleutel="head.permissions" />
        <div class="op-list">
          {/* "OP AANBOD:" — vult deze policy meer dan één aanbod in, dan worden
              haar eigen toestemmingen per aanbod ingedeeld (agreementOps). Die
              onderverdeling zit BINNEN deze sectie: het is een tweede snede door
              dezelfde toestemmingen, niet een vierde soort. De naam van het
              aanbod is hier nog gedempte tekst en geen sprong — dat is taak 3/8. */}
          <For each={secties() || []}>{(sec) => (
            <>
              <div class="agr-offer-sec">
                <Show when={sec.aanbod} fallback={tekst('agr.otherPermissions')}>{(off) => (
                  <>{tekst('agr.onOffer')}<span class="offer-naam">{off().title}</span></>
                )}</Show>
              </div>
              <For each={groepeer(sec.regels)}>{(knoop) => (
                <Regelknoop
                  knoop={knoop}
                  soort="toestemming"
                  eigenaar={eigenaar()}
                  scope={props.pol.iri}
                  getoondeDims={[]}
                  ouder={props.pol}
                />
              )}</For>
            </>
          )}</For>
          <For each={toestemmingKnopen()}>{(knoop) => (
            <Regelknoop
              knoop={knoop}
              soort="toestemming"
              eigenaar={eigenaar()}
              scope={props.pol.iri}
              getoondeDims={[]}
              ouder={props.pol}
            />
          )}</For>
          {/* ÉÉN "+ toestemming" achter ALLE aanbodsubsecties, niet één per
              subsectie. Een chip binnen "Op aanbod X" zou beloven dat de nieuwe
              toestemming uit dát aanbod komt — een afleiding (`derivedFrom`/
              gedeelde actie) die de toevoeging niet legt. Eén toevoegplek per
              soort, zoals overal in deze lijst. */}
          {sectieGhost('toestemming')}
        </div>
      </Show>

      {/* --- 3. VERBODEN (odrl:prohibition) ------------------------------ */}
      <Show when={heeftSectie('verbod')}>
        <SectieKop soort="verbod" sleutel="head.prohibitions" />
        <div class="op-list">
          <For each={verbodKnopen()}>{(knoop) => (
            <Regelknoop
              knoop={knoop}
              soort="verbod"
              eigenaar={eigenaar()}
              scope={props.pol.iri}
              getoondeDims={[]}
              ouder={props.pol}
            />
          )}</For>
          {sectieGhost('verbod')}
        </div>
      </Show>

      {/* WAT ER VAN HET VERZAMELBLOK OVERBLIJFT: alleen de soorten waarvan deze
          kaart nog geen enkele regel heeft. Zij hebben geen sectie om achteraan
          te staan, en een lege sectiekop bouwen om er één chip in te hangen is
          de C-1-fout. Heeft de kaart van alle drie de soorten al iets, dan staat
          hier niets meer.

          TWEE POORTEN, en de tweede is review-bevinding B1: `zonderSectie()` is
          een DATA-vraag (welke soorten hebben nog geen regel) en zegt niets over
          de stand. Zonder `bewerklaagActief()` bleef op een kaart met deels
          ontbrekende soorten in de KIJKSTAND een lege `<div class="op-list">`
          achter — de `<Haak>` erbinnen tekent daar terecht niets, dus stond er
          een omhulsel om niets. Dezelfde familie als de 44 lege koppen van golf
          B (review C-1): de haak deed het goed, de OMHULLENDE poort niet.

          Deze poort en niet `weergave.editMode` alleen: `bewerklaagActief()` is
          precies de poort die `Haak` zelf draagt (stand aan ÉN laag geladen), en
          twee poorten die uiteenlopen zijn hoe het gat opnieuw ontstaat. */}
      <Show when={zonderSectie().length && bewerklaagActief()}>
        <div class="op-list">
          <Haak
            naam="kaartGhost"
            ctx={{
              pol: props.pol,
              soort: props.soort,
              soorten: zonderSectie(),
              plaatsing: 'verzamel',
            }}
          />
        </div>
      </Show>
      {/* …en daaronder, ALLEEN op een aanbod, de ghost-KAART voor de tweede
          trap van het drietraps. */}
      <Show when={props.soort === 'offer'}>
        <Haak naam="overeenkomstGhost" ctx={{ pol: props.pol, soort: props.soort }} />
      </Show>
    </Show>
  );
}
