// Instap van de nieuwe app: profielbundel halen, URL lezen, dan mounten.
//
// De volgorde telt, en er is sinds 16 sep 2026 één stap bij gekomen die vóór
// alle andere moet.
//
//   1. DE PROFIELBUNDEL (`data/profiel.json`). Hij bepaalt welke vocabulaire
//      automatisch meelaadt, welke registerprefixen bestaan, welke klassen
//      machine-uitvoerbaar beleid aanduiden, wat de bewerkdropdowns aanbieden
//      en welke taal een bezoeker zonder `?lang=` krijgt. Alle drie de stappen
//      hieronder lezen hem, dus hij is er eerder dan zij. Ontbreekt hij, dan is
//      de viewer puur generiek — dat is de normale kale stand en geen fout.
//   2. `registreerStandaarden()` — de prefixen en weergavenamen, op precies de
//      plek waar zij altijd al stonden: vóór de taalkeuze en vóór de eerste
//      render.
//   3. `leesUitUrl()` — zet ook de taal in de modellaag (i18n.js), en parse.js
//      leest die instelling voor zijn labelvoorkeur; dus vóór de eerste render.
//
// WAAROM DE RENDER OP DE FETCH WACHT. De bundel draagt de chrome-taal, en die
// is niet na te leveren zonder de hele app opnieuw te tekenen: een render in
// 'en' die een tel later 'nl' wordt is een zichtbare flits, en op de plekken
// waar de taal in een ref of een cache belandt (taalKeten, de labelsleuf) is
// het meer dan een flits. Het is één klein bestand naast de app, op dezelfde
// host als de app zelf; wie hem niet heeft, betaalt één 404.
import { render } from 'solid-js/web';
import { App } from './app.jsx';
import { EXAMPLES_BASE } from './model/default-corpus.js';
import { haalProfiel, setProfiel } from './model/profiel.js';
import { registreerStandaarden } from './model-registers.js';
import { leesUitUrl } from './stores/weergave.js';
import './app.css';

async function start() {
  const { profiel, fouten } = await haalProfiel(EXAMPLES_BASE);
  setProfiel(profiel);
  // Een KAPOTTE bundel (stukke JSON, een beloofde shape die 404't) is een
  // deployment-fout en geen gebruikersfout: hij hoort in de console van wie de
  // uitrol deed, niet in de meldingenbalk van wie de policy leest.
  for (const f of fouten) console.error(`profielbundel: ${f.url} — ${f.message}`);
  registreerStandaarden();
  leesUitUrl(location.search);
  render(() => <App />, document.getElementById('app')!);
}

void start();
