// De BOOM van de zijnav: de beleidshiërarchie als platte rijenlijst.
//
// Gedragsbron: viewer-bevroren/assets/tree-view.js (treeRows/visibleRows/renderTree) plus
// het onSelect/onToggle-blok van renderTreeNav in viewer-bevroren/assets/doc.js. De
// structuur is met opzet PLAT gebleven — rijen als zusters in één scrollende
// kolom, met de diepte als klasse (depth-0..3) in plaats van als DOM-nesting.
// Genest renderen zou per niveau een extra element opleveren en de bestaande
// inspringing (.tree-row.depth-N in de stylesheet) betekenisloos maken; de
// vlakke lijst is bovendien wat de oude viewer neerzet, en dat is de pariteit
// die deze taak moet halen.
//
// De twee vormfuncties staan hier (niet in src/model/): ze horen bij DEZE
// weergave — een andere presentatie van dezelfde nav zou andere rijen willen —
// en de bevroren tree-view.js verdwijnt met deeltraject 4. Ze zijn DOM-vrij en
// los getoetst.
//
// De inklap-voorkeur (welke knopen dicht staan) hoort bij de boom en woont dus
// hier: alleen de boom leest en schrijft hem. Hij komt bij het opbouwen uit
// localStorage (prefs.js) en gaat er bij elke klik weer in — precies zoals
// treeClosed/prefSet('tree.closed') in de bevroren viewer.
import { createMemo, createSignal, For, Show } from 'solid-js';
import { prefGet, prefSet } from '../../model/prefs.js';

/** Eén knoop uit buildNav (src/model/parse.js). Alleen de velden die de boom
 *  tekent; de nav draagt er meer (role, containerIri, permIndex, sourceIri) en
 *  die blijven onaangeroerd. */
export interface NavKnoop {
  id: string;
  label: string;
  kind?: string;
  badge?: string | null;
  children?: NavKnoop[];
}

/** Eén getekende rij: de knoop plus zijn plaats in de boom. */
export interface NavRij {
  id: string;
  label: string;
  kind: string;
  badge: string | null;
  depth: number;
  parentId: string | null;
  heeftKinderen: boolean;
}

/** Boom -> platte rijen, in leesvolgorde (ouder vóór kind). */
export function navRijen(
  nav: NavKnoop[] | null | undefined,
  depth = 0,
  parentId: string | null = null,
  uit: NavRij[] = [],
): NavRij[] {
  for (const knoop of nav || []) {
    const kinderen = knoop.children || [];
    uit.push({
      id: knoop.id, label: knoop.label, kind: knoop.kind || '',
      badge: knoop.badge || null, depth, parentId,
      heeftKinderen: kinderen.length > 0,
    });
    navRijen(kinderen, depth + 1, knoop.id, uit);
  }
  return uit;
}

/** Rijen minus alles onder een dichtgeklapte knoop. Ook KLEINkinderen vallen
 *  weg: een rij waarvan de ouder al verborgen is, verbergt zichzelf mee. */
export function zichtbareRijen(rijen: NavRij[], dicht: ReadonlySet<string>): NavRij[] {
  const verborgen = new Set<string>();
  const zicht: NavRij[] = [];
  for (const r of rijen) {
    if (r.parentId !== null && (dicht.has(r.parentId) || verborgen.has(r.parentId))) {
      verborgen.add(r.id);
      continue;
    }
    zicht.push(r);
  }
  return zicht;
}

const GEEN_DICHTE: ReadonlySet<string> = new Set<string>();

export interface BoomProps {
  /** De (eventueel gefilterde) navigatieboom. */
  nav: NavKnoop[];
  /** Een rij aanwijzen. De boom oordeelt niet over de id — dat doet de zijnav. */
  onSelect: (id: string) => void;
  /** De gescopete policy (?policy=/?set=), als lichte markering. */
  selected?: string | null;
  /** Tijdens een actief tekstfilter telt de inklap-voorkeur niet: een match
   *  onder een dichtgeklapte tak hoort zichtbaar te zijn. De voorkeur zelf
   *  verandert niet — zodra het filter leeg is geldt zij weer. */
  negeerDicht?: boolean;
}

export function Boom(props: BoomProps) {
  const bewaard = prefGet('tree.closed', []);
  const [dicht, setDicht] = createSignal<ReadonlySet<string>>(
    new Set<string>(Array.isArray(bewaard) ? (bewaard as string[]) : []));
  const rijen = createMemo(() => navRijen(props.nav));
  const zicht = createMemo(() => zichtbareRijen(
    rijen(), props.negeerDicht ? GEEN_DICHTE : dicht()));

  let lijf!: HTMLDivElement;

  const staatDicht = (id: string) => !props.negeerDicht && dicht().has(id);

  function klap(id: string) {
    const volgend = new Set(dicht());
    if (volgend.has(id)) volgend.delete(id); else volgend.add(id);
    setDicht(volgend);
    prefSet('tree.closed', [...volgend]);
    // De rij waarop de focus stond is bij het herbouwen vervangen. Zonder deze
    // teruggave valt de focus naar de body en kan wie met het toetsenbord
    // dichtklapte de knoop niet meer openen.
    const rij = [...lijf.children].find(
      (n) => n.getAttribute && n.getAttribute('data-id') === id) as HTMLElement | undefined;
    rij?.focus?.();
  }

  return (
    <div class="tree-body" ref={lijf}>
      <For each={zicht()}>{(r) => (
        <div
          class={'tree-row depth-' + Math.min(r.depth, 3)
            + (r.id === props.selected ? ' selected' : '')}
          data-id={r.id}
          role="button"
          tabindex="0"
          // Alleen op rijen die iets te openen hebben: een blad met
          // aria-expanded belooft een schermlezer kinderen die er niet zijn.
          aria-expanded={r.heeftKinderen ? !staatDicht(r.id) : undefined}
          onClick={() => props.onSelect(r.id)}
          // Enter/spatie = de rij aanwijzen (zelfde als een klik); ←/→ klappen
          // de knoop dicht/open. Zonder die twee toetsen was in- en uitklappen
          // alleen met de muis te doen: het driehoekje is aria-hidden en krijgt
          // geen focus.
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              props.onSelect(r.id);
            } else if (r.heeftKinderen
              && (e.key === 'ArrowRight' ? staatDicht(r.id)
                : e.key === 'ArrowLeft' && !staatDicht(r.id))) {
              e.preventDefault();
              klap(r.id);
            }
          }}
        >
          <Show
            when={r.heeftKinderen}
            fallback={<span class="tree-toggle tree-leaf" aria-hidden="true" />}
          >
            <span
              class="tree-toggle"
              aria-hidden="true"
              onClick={(e) => { e.stopPropagation(); klap(r.id); }}
            >{staatDicht(r.id) ? '▸' : '▾'}</span>
          </Show>
          <span class="tree-label" title={r.label}>{r.label}</span>
          <Show when={r.badge}>{(b) => (
            <span class={'tree-badge ' + r.kind}>{b()}</span>
          )}</Show>
        </div>
      )}</For>
    </div>
  );
}
